import React, { useEffect, useMemo, useRef, useState } from 'react';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';
import { THEME_MODE_STORAGE_KEY } from '../../context/ThemeModeContext';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Alert,
  Box,
  Button,
  Checkbox,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  MenuItem,
  Paper,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import { REVIEW_CATEGORIES, categoryLabel } from './expertReviewCategories';
import ExpertScope3LinkFields, { scope3CategoryPayload } from './ExpertScope3LinkFields';
import {
  ExpertReviewRow,
  REVIEW_UNITS,
  canApproveAsIs,
  canSelectForSharedAssessment,
  categoryNeedsRegisteredActivity,
  resolutionBlocksApproval,
  recommendationCanApply,
  businessStatusLabel,
  orderedReview,
  resolutionHeadline,
  reviewClassLabel,
  similarOpenRows,
  voucherFacts,
} from './expertReviewDisplay';

export type ReviewStep = 'understand' | 'recommendation' | 'correct' | 'send';

interface DecisionHistoryEntry {
  decisionId: string;
  decision: string;
  reviewerName?: string;
  reviewedAt?: string;
  note?: string;
  isCurrent?: boolean;
}

interface ClarificationHistoryEvent {
  roundId: string;
  eventType: string;
  question?: string;
  reply?: string;
  documentId?: string;
  documentName?: string;
  actorName?: string;
  actorRole?: string;
  occurredAt?: string;
  previousRequest?: { question?: string } | null;
}

const CLARIFICATION_EVENT_TYPES = new Set(['requested', 'answered', 'cancelled', 'reviewed']);

const clarificationEventLabel = (eventType: string) => {
  if (eventType === 'requested') return 'Request';
  if (eventType === 'answered') return 'Company reply';
  if (eventType === 'cancelled') return 'Cancelled';
  if (eventType === 'reviewed') return 'Expert review';
  return eventType;
};

const formatClarificationTime = (value?: string) => {
  if (!value) return '';
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return '';
  return parsed.toLocaleString();
};

const decisionLabel = (decision: string) => {
  if (decision === 'confirmed') return 'Confirmed';
  if (decision === 'corrected') return 'Corrected';
  if (decision === 'rejected') return 'Rejected';
  return decision;
};

const STEP_ORDER: ReviewStep[] = ['understand', 'recommendation', 'correct', 'send'];
const STEP_LABELS: Record<ReviewStep, string> = {
  understand: '1. Transaction',
  recommendation: '2. Recommendation',
  correct: '3. Correct',
  send: '4. Send back',
};

export interface CorrectionAssistanceView {
  needsAssistance: boolean;
  referToRecommendation: boolean;
  message: string;
  apply?: {
    category?: string;
    quantity?: number | null;
    subcategory?: string;
    unit?: string;
    factorId?: string;
    factorLabel?: string;
  } | null;
  outcome?: string;
}

const focusWithRing = (node: HTMLElement | null | undefined) => {
  if (!node) return;
  node.focus();
  const dark = window.localStorage.getItem(THEME_MODE_STORAGE_KEY) === 'dark';
  node.style.outline = `2px solid ${dark ? '#ffffff' : '#2e7d32'}`;
  node.style.outlineOffset = '2px';
  const clear = () => {
    node.style.outline = '';
    node.style.outlineOffset = '';
    node.removeEventListener('blur', clear);
  };
  node.addEventListener('blur', clear);
};

const ExpertReviewWizard: React.FC<{
  rows: ExpertReviewRow[];
  busyId: string | null;
  askingId: string | null;
  assistanceById: Record<string, CorrectionAssistanceView>;
  onAskAgent: (row: ExpertReviewRow) => void;
  onAskCompany: (row: ExpertReviewRow, request: { kind: 'details' | 'bill'; question: string }) => void;
  onCancelRequest: (row: ExpertReviewRow) => void;
  onReviewReply?: (row: ExpertReviewRow) => void;
  onConfirm: (row: ExpertReviewRow, scope3Category?: number) => void;
  onCorrect: (row: ExpertReviewRow, draft: { category: string; subcategory?: string; quantity: string; unit: string; scope3Category?: string }) => void;
  onReject?: (row: ExpertReviewRow, reason: string) => void;
  selectedIds?: string[];
  onToggle?: (id: string) => void;
  onSelectSimilar?: (row: ExpertReviewRow) => void;
  initialTransactionId?: string | null;
  embedded?: boolean;
  activeTransactionId?: string | null;
  onActiveTransactionId?: (id: string | null) => void;
}> = ({
  rows,
  busyId,
  askingId,
  assistanceById,
  onAskAgent,
  onAskCompany,
  onCancelRequest,
  onReviewReply,
  onConfirm,
  onCorrect,
  onReject,
  selectedIds = [],
  onToggle,
  onSelectSimilar,
  initialTransactionId = null,
  embedded = false,
  activeTransactionId = null,
  onActiveTransactionId,
}) => {
  const plan = useMemo(() => orderedReview(rows), [rows]);
  const ordered = plan.transactions;
  const stageFor = (id: string) => plan.stages.find((stage) => stage.transactionIds.includes(id));
  const rowsRef = useRef(rows);
  rowsRef.current = rows;
  const membership = rows.map((item) => item._id).join('|');
  const stableIds = useMemo(() => (
    orderedReview(rowsRef.current).transactions.map((item) => item._id)
  ), [membership]); // eslint-disable-line react-hooks/exhaustive-deps -- membership is the page identity; rows are read through a ref so a save does not reorder next and previous.
  const [internalActiveId, setInternalActiveId] = useState<string | null>(initialTransactionId || null);
  const activeId = onActiveTransactionId ? (activeTransactionId ?? null) : internalActiveId;
  const setActiveId = (id: string | null) => {
    if (!onActiveTransactionId) setInternalActiveId(id);
    onActiveTransactionId?.(id);
  };
  useEffect(() => {
    if (!onActiveTransactionId && initialTransactionId) setInternalActiveId(initialTransactionId);
  }, [initialTransactionId, onActiveTransactionId]);
  const [step, setStep] = useState<ReviewStep>('understand');
  const detailBodyRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!activeId) return;
    const item = rowsRef.current.find((entry) => entry._id === activeId);
    if (!item) return;
    setStep(item.informationRequest?.status === 'open' ? 'send' : 'understand');
    if (detailBodyRef.current) detailBodyRef.current.scrollTop = 0;
  }, [activeId]);
  const [drafts, setDrafts] = useState<Record<string, { category: string; subcategory: string; quantity: string; unit: string; scope3Category: string }>>({});
  const [questions, setQuestions] = useState<Record<string, string>>({});
  const [rejectOpen, setRejectOpen] = useState(false);
  const rejectOpenerRef = useState(() => ({ current: null as HTMLButtonElement | null }))[0];
  const closeRejectDialog = () => {
    setRejectOpen(false);
    window.setTimeout(() => focusWithRing(rejectOpenerRef.current), 0);
  };
  const [rejectReason, setRejectReason] = useState('');
  const [historyError, setHistoryError] = useState<string | null>(null);
  const [historyAttempt, setHistoryAttempt] = useState(0);
  const [decisionHistory, setDecisionHistory] = useState<DecisionHistoryEntry[]>([]);
  const [clarificationHistory, setClarificationHistory] = useState<ClarificationHistoryEvent[]>([]);
  const [factorException, setFactorException] = useState<{ exceptionType?: string; severity?: string; status?: string; reason?: string; factorId?: string; attemptedFactorId?: string; factorVersion?: string; provisional?: boolean; message?: string; evidenceDocumentId?: string } | null>(null);
  const [factorEvents, setFactorEvents] = useState<Array<{ eventType?: string; actorName?: string; occurredAt?: string; note?: string }>>([]);
  const [exceptionFactorId, setExceptionFactorId] = useState('');
  const [exceptionReason, setExceptionReason] = useState('');
  const [exceptionEvidence, setExceptionEvidence] = useState('');
  const [exceptionBusy, setExceptionBusy] = useState(false);
  const [exceptionError, setExceptionError] = useState('');
  const [exceptionNotice, setExceptionNotice] = useState('');
  const [exceptionReload, setExceptionReload] = useState(0);
  const row = ordered.find((item) => item._id === activeId) || null;
  const clarificationStamp = [
    row?.informationRequest?.status || '',
    row?.informationRequest?.question || '',
    row?.informationRequest?.reply || '',
    row?.informationRequest?.documentName || '',
  ].join('|');

  useEffect(() => {
    if (!activeId) {
      setDecisionHistory([]);
      return undefined;
    }
    let cancelled = false;
    const loadHistory = async () => {
      try {
        const response = await axios.get(buildApiUrl(`/expert/transactions/${activeId}/decision-history`), {
          headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
          params: { msmeId: row?.msmeId || '' },
        });
        const entries = response?.data?.data?.entries;
        if (!cancelled) {
          setHistoryError(null);
          setDecisionHistory(Array.isArray(entries) ? entries : []);
        }
      } catch (error: any) {
        if (!cancelled) {
          setDecisionHistory([]);
          setHistoryError(error?.response?.data?.message || 'Decision history could not be loaded.');
        }
      }
    };
    loadHistory();
    return () => {
      cancelled = true;
    };
  }, [activeId, historyAttempt, row?.msmeId]);

  useEffect(() => {
    if (step !== 'send' || !activeId) {
      return undefined;
    }
    let cancelled = false;
    const loadClarificationHistory = async () => {
      try {
        const response = await axios.get(buildApiUrl(`/expert/transactions/${activeId}/clarification-history`), {
          headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
          params: { msmeId: row?.msmeId || '' },
        });
        const entries = response?.data?.data?.entries;
        const history = Array.isArray(entries)
          ? entries.filter((entry) => entry && CLARIFICATION_EVENT_TYPES.has(entry.eventType))
          : [];
        if (!cancelled) {
          setHistoryError(null);
          setClarificationHistory(history);
        }
      } catch (error: any) {
        if (!cancelled) {
          setClarificationHistory([]);
          setHistoryError(error?.response?.data?.message || 'Clarification history could not be loaded.');
        }
      }
    };
    loadClarificationHistory();
    return () => {
      cancelled = true;
    };
  }, [activeId, step, clarificationStamp, row?.msmeId]);

  useEffect(() => {
    if (!activeId) {
      setFactorException(null);
      setFactorEvents([]);
      setExceptionFactorId('');
      setExceptionReason('');
      setExceptionEvidence('');
      setExceptionError('');
      return undefined;
    }
    let cancelled = false;
    const loadException = async () => {
      try {
        const response = await axios.get(buildApiUrl(`/expert/transactions/${activeId}/factor-exception`), {
          headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
          params: { msmeId: row?.msmeId || '' },
        });
        const exception = response?.data?.data?.exception;
        const events = response?.data?.data?.events;
        if (cancelled) return;
        setFactorException(exception?.exceptionType ? exception : null);
        setFactorEvents(Array.isArray(events) ? events.filter((event) => event?.eventType && event?.exceptionId) : []);
        if (exception?.exceptionType) {
          setExceptionFactorId(exception.factorId || exception.attemptedFactorId || '');
        }
      } catch (error) {
        if (!cancelled) {
          setFactorException(null);
          setFactorEvents([]);
          const message = axios.isAxiosError(error) ? error.response?.data?.message : undefined;
          setHistoryError(typeof message === 'string' && message ? message : 'The factor exception could not be loaded.');
        }
      }
    };
    loadException();
    return () => {
      cancelled = true;
    };
  }, [activeId, exceptionReload, row?.msmeId]);

  const exceptionLock = useRef(false);
  const authHeaders = () => ({ Authorization: `Bearer ${localStorage.getItem('token')}` });

  const assignException = async () => {
    if (!activeId || factorException?.status !== 'open' || exceptionLock.current) return;
    exceptionLock.current = true;
    setExceptionBusy(true);
    setExceptionError('');
    setExceptionNotice('');
    try {
      await axios.post(buildApiUrl(`/expert/transactions/${activeId}/factor-exception/assign`), {
        msmeId: row?.msmeId || '',
        batchId: row?.batchId || undefined
      }, { headers: authHeaders() });
      setExceptionNotice('Exception assigned. The calculation is not approved.');
      setExceptionReload((value) => value + 1);
    } catch (error) {
      const message = axios.isAxiosError(error) ? error.response?.data?.message : '';
      setExceptionError(message || 'The exception was not assigned.');
    } finally {
      exceptionLock.current = false;
      setExceptionBusy(false);
    }
  };

  const resolveException = async () => {
    if (!activeId || exceptionLock.current) return;
    if (!exceptionEvidence.trim()) {
      setExceptionError('An evidence reference is required.');
      return;
    }
    if (exceptionReason.trim().length < 8) return;
    exceptionLock.current = true;
    setExceptionBusy(true);
    setExceptionError('');
    try {
      await axios.post(buildApiUrl(`/expert/transactions/${activeId}/factor-exception/resolve`), {
        msmeId: row?.msmeId || '',
        batchId: row?.batchId || undefined,
        factorId: exceptionFactorId.trim(),
        reason: exceptionReason.trim(),
        evidenceDocumentId: exceptionEvidence.trim(),
        recalculate: true
      }, { headers: authHeaders() });
      setExceptionReason('');
      setExceptionEvidence('');
      setExceptionNotice('Exception resolved. The calculation is not approved.');
      setExceptionReload((value) => value + 1);
    } catch (error) {
      const message = axios.isAxiosError(error)
        ? error.response?.data?.message
        : '';
      setExceptionError(message || 'The exception was not resolved.');
    } finally {
      exceptionLock.current = false;
      setExceptionBusy(false);
    }
  };

  const clarificationRounds = useMemo(() => {
    const groups: { roundId: string; events: ClarificationHistoryEvent[] }[] = [];
    clarificationHistory.forEach((event) => {
      const last = groups[groups.length - 1];
      if (!last || last.roundId !== event.roundId) {
        groups.push({ roundId: event.roundId, events: [event] });
      } else {
        last.events.push(event);
      }
    });
    return groups;
  }, [clarificationHistory]);
  const openRows = ordered.filter((item) => !item.settled);
  const index = row ? openRows.findIndex((item) => item._id === row._id) : -1;

  const draftFor = (item: ExpertReviewRow) => {
    const saved = drafts[item._id];
    if (saved) return saved;
    const suggested = item.recommendation;
    const usable = suggested?.available !== false;
    return {
      category: (usable && suggested?.category) || item.category || 'other',
      subcategory: (usable && suggested?.subcategory) || item.subcategory || '',
      quantity: usable && suggested?.quantity != null
        ? String(suggested.quantity)
        : (item.quantity != null ? String(item.quantity) : ''),
      unit: (usable && suggested?.unit) || item.unit || '',
      scope3Category: '',
    };
  };

  const openRow = (item: ExpertReviewRow) => {
    setActiveId(item._id);
    setStep(item.informationRequest?.status === 'open' ? 'send' : 'understand');
  };

  const applyRecommendation = (item: ExpertReviewRow, apply?: CorrectionAssistanceView['apply']) => {
    if (!recommendationCanApply(item, assistanceById[item._id])) return;
    const suggested = item.recommendation;
    setDrafts((current) => ({
      ...current,
      [item._id]: {
        category: apply?.category || (suggested?.available !== false && suggested?.category) || item.category || 'other',
        subcategory: apply?.subcategory || (suggested?.available !== false && suggested?.subcategory) || item.subcategory || '',
        quantity: apply?.quantity != null
          ? String(apply.quantity)
          : (suggested?.available !== false && suggested?.quantity != null ? String(suggested.quantity) : (item.quantity != null ? String(item.quantity) : '')),
        unit: apply?.unit || (suggested?.available !== false && suggested?.unit) || item.unit || '',
        scope3Category: drafts[item._id]?.scope3Category || '',
      },
    }));
    setStep('correct');
  };

  const latestById = new Map(rows.map((item) => [item._id, item]));
  const plannedById = new Map(ordered.map((item) => [item._id, item]));
  const sequence = stableIds.map((id) => {
    const latest = latestById.get(id);
    if (!latest) return null;
    const planned = plannedById.get(id);
    return planned
      ? { ...planned, ...latest, reviewStage: planned.reviewStage, reviewOrder: planned.reviewOrder }
      : latest;
  }).filter((item): item is ExpertReviewRow => Boolean(item));
  rows.forEach((item) => {
    if (!sequence.some((existing) => existing._id === item._id)) sequence.push(item);
  });
  const sequenceIndex = row ? sequence.findIndex((item) => item._id === row._id) : -1;
  const previousRow = sequenceIndex > 0 ? sequence[sequenceIndex - 1] : null;
  const nextRow = sequenceIndex >= 0 && sequenceIndex + 1 < sequence.length ? sequence[sequenceIndex + 1] : null;
  const nextOpen = sequenceIndex >= 0
    ? sequence.slice(sequenceIndex + 1).find((item) => !item.settled) || null
    : sequence.find((item) => !item.settled) || null;
  const nextLabel = nextOpen?.reviewStage === 'uncertain'
    ? 'Next uncertain transaction'
    : nextOpen?.reviewStage === 'key'
      ? 'Next key transaction'
      : nextOpen?.reviewStage === 'waiting'
        ? 'Next transaction waiting on the company'
        : nextOpen?.reviewStage === 'calculated'
          ? 'Next calculated transaction'
          : 'Next transaction';

  if (!row) {
    if (embedded) return null;
    const firstOpen = openRows[0];
    const startLabel = firstOpen?.reviewStage === 'key'
      ? 'Review the next key transaction'
      : firstOpen?.reviewStage === 'calculated'
        ? 'Review the next calculated transaction'
        : 'Review the next uncertain transaction';
    return (
      <Stack spacing={1.5}>
        <Typography variant="body2" color="text.secondary">
          {openRows.length
            ? `${openRows.length} transaction${openRows.length === 1 ? '' : 's'} still need a decision. Uncertain transactions come first. Key transactions follow.`
            : 'Every open transaction on this list has a decision.'}
        </Typography>
        {firstOpen ? (
          <Button variant="contained" onClick={() => openRow(firstOpen)} sx={{ alignSelf: 'flex-start' }}>
            {startLabel}
          </Button>
        ) : null}
        {plan.stages.map((stage) => (
          <Stack key={stage.id} spacing={1}>
            <Box>
              <Typography variant="subtitle1" sx={{ fontWeight: 800 }}>{`${stage.title} · ${stage.open} open`}</Typography>
              <Typography variant="body2" color="text.secondary">{stage.instruction}</Typography>
            </Box>
            {ordered.filter((item) => item.reviewStage === stage.id).map((item) => (
          <Paper key={item._id} variant="outlined" sx={{ p: 1.5 }}>
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} alignItems={{ sm: 'center' }}>
              <Checkbox
                checked={selectedIds.includes(item._id)}
                disabled={!canSelectForSharedAssessment(item)}
                inputProps={{ 'aria-label': `Select ${item.description || 'this transaction'}` }}
                onChange={() => onToggle?.(item._id)}
              />
              <Box sx={{ flex: 1 }}>
                <Typography variant="subtitle2">{item.description || 'Untitled voucher'}</Typography>
                <Typography variant="caption" color="text.secondary">
                  {reviewClassLabel(item)}
                  {businessStatusLabel(item) ? ` · ${businessStatusLabel(item)}` : ''}
                  {item.settled ? ' · Approved' : item.informationRequest?.status === 'open' ? ' · Waiting for the company' : ''}
                </Typography>
              </Box>
              {similarOpenRows(ordered, item).length > 1 ? (
                <Button size="small" onClick={() => onSelectSimilar?.(item)}>
                  {`Select similar to ${item.description || 'this transaction'}`}
                </Button>
              ) : null}
              <Button size="small" variant="contained" onClick={() => openRow(item)}>
                {item.settled ? 'View' : `Review ${item.description || 'this transaction'}`}
              </Button>
            </Stack>
          </Paper>
            ))}
          </Stack>
        ))}
      </Stack>
    );
  }

  const facts = voucherFacts(row);
  const draft = draftFor(row);
  const assistance = assistanceById[row._id];
  const request = row.informationRequest;
  const waiting = request?.status === 'open';
  const busy = busyId === row._id;
  const units = REVIEW_UNITS.includes(draft.unit) || draft.unit === ''
    ? REVIEW_UNITS
    : [draft.unit, ...REVIEW_UNITS];
  const categoryValue = REVIEW_CATEGORIES.includes(draft.category as typeof REVIEW_CATEGORIES[number])
    ? draft.category
    : 'other';

  return (
    <>
    <Box sx={embedded ? {
      display: 'flex',
      flexDirection: 'column',
      flex: 1,
      minHeight: 0,
      overflow: 'hidden',
    } : undefined}
    >
    <Box sx={embedded ? { flex: '0 0 auto', bgcolor: 'background.paper', zIndex: 2, pb: 1 } : undefined}>
    <Stack spacing={embedded ? 1 : 2}>
      <Stack
        direction="row"
        spacing={1}
        alignItems="center"
        flexWrap="wrap"
        useFlexGap
        sx={embedded ? { py: 0.5 } : undefined}
      >
        {embedded ? null : (
          <Checkbox
            checked={selectedIds.includes(row._id)}
            disabled={!canSelectForSharedAssessment(row)}
            inputProps={{ 'aria-label': `Select ${row.description || 'this transaction'}` }}
            onChange={() => onToggle?.(row._id)}
          />
        )}
        <Button size="small" onClick={() => setActiveId(null)}>{embedded ? 'Back to table' : 'All transactions'}</Button>
        <Typography variant="body2" color="text.secondary">
          {embedded
            ? (sequenceIndex >= 0 ? `${sequenceIndex + 1} of ${sequence.length}` : 'Reviewed')
            : (index >= 0 ? `Transaction ${index + 1} of ${openRows.length}` : 'Reviewed')}
        </Typography>
        {stageFor(row._id) ? <Chip size="small" label={stageFor(row._id)?.title || ''} /> : null}
        {embedded ? (
          <>
            <Button size="small" variant="outlined" aria-label="Previous transaction" disabled={!previousRow} onClick={() => { if (previousRow) openRow(previousRow); }}>
              Previous
            </Button>
            <Button size="small" variant="outlined" aria-label="Next transaction" disabled={!nextRow} onClick={() => { if (nextRow) openRow(nextRow); }}>
              Next
            </Button>
          </>
        ) : nextOpen ? (
          <Button size="small" variant="outlined" onClick={() => openRow(nextOpen)}>{nextLabel}</Button>
        ) : null}
      </Stack>
      <Box sx={{ display: 'grid', gridTemplateColumns: embedded ? '1fr 1fr' : { xs: '1fr 1fr', md: 'repeat(4, 1fr)' }, gap: 0.75 }}>
        {STEP_ORDER.map((item, stepIndex) => {
          const current = step === item;
          const complete = STEP_ORDER.indexOf(step) > stepIndex;
          return (
            <Chip
              key={item}
              label={STEP_LABELS[item]}
              color={current ? 'primary' : 'default'}
              variant={current ? 'filled' : 'outlined'}
              aria-current={current ? 'step' : undefined}
              onClick={() => setStep(item)}
              sx={{
                width: '100%',
                justifyContent: 'center',
                '& .MuiChip-label': { px: 0.75 },
                ...(complete && !current ? { borderColor: 'primary.main' } : {}),
              }}
            />
          );
        })}
      </Box>
    </Stack>
    </Box>
    <Box ref={detailBodyRef} sx={embedded ? { flex: 1, minHeight: 0, overflowY: 'auto' } : undefined}>
    <Stack spacing={2}>

      {step === 'understand' ? (
        <Paper variant="outlined" sx={{ p: 2 }}>
          <Typography variant="h6" sx={{ fontWeight: 800 }}>{row.description || 'Untitled voucher'}</Typography>
          <Box sx={{ display: 'grid', gridTemplateColumns: embedded ? '1fr 1fr' : { xs: '1fr 1fr', sm: 'repeat(4, 1fr)' }, gap: 1, mt: 1.5 }}>
            <Fact label="Category" value={categoryLabel(row.category)} />
            <Fact label="Quantity" value={row.quantity != null ? String(row.quantity) : '—'} />
            <Fact label="Unit" value={row.unit || '—'} />
            <Fact label="kg CO2e" value={String(facts.kilograms)} />
          </Box>
          <Box sx={{ mt: 1.5 }}>
            <Typography variant="caption" color="text.secondary">Reason</Typography>
            <Typography variant="body2" sx={{ fontWeight: 700 }}>
              {resolutionHeadline(row) || row.businessStatusReason || reviewClassLabel(row)}
            </Typography>
          </Box>
          <Stack direction="row" spacing={1} sx={{ mt: 1 }} flexWrap="wrap" useFlexGap>
            <Chip size="small" label={reviewClassLabel(row)} />
            {businessStatusLabel(row) ? <Chip size="small" label={businessStatusLabel(row)} /> : null}
          </Stack>
          {factorException ? (
            <Fold embedded={embedded} title="Factor exception">
              <Typography variant="body2">{`${factorException.exceptionType} · ${factorException.severity || 'high'} · ${factorException.status}`}</Typography>
              <Typography variant="body2">{factorException.reason || factorException.message}</Typography>
              {factorException.factorId || factorException.attemptedFactorId ? (
                <Typography variant="body2">
                  {`Factor ${factorException.factorId || factorException.attemptedFactorId}${factorException.factorVersion ? ` · ${factorException.factorVersion}` : ''}`}
                </Typography>
              ) : null}
              {factorException.evidenceDocumentId ? (
                <Typography variant="body2">{`Evidence ${factorException.evidenceDocumentId}`}</Typography>
              ) : null}
              {factorException.provisional ? <Typography variant="body2">Provisional calculation. Official reports stay closed.</Typography> : null}
              {factorException.exceptionType === 'outdated_factor' ? <Typography variant="body2">Stored calculation is unchanged until an expert recalculates it.</Typography> : null}
              {factorEvents.map((event, index) => (
                <Typography key={`${event.eventType}-${event.occurredAt || index}`} variant="caption" display="block">
                  {`${event.eventType}${event.actorName ? ` · ${event.actorName}` : ''}${event.occurredAt ? ` · ${new Date(event.occurredAt).toLocaleString()}` : ''}`}
                </Typography>
              ))}
              {factorException.status === 'open' ? (
                <Button sx={{ mt: 1 }} variant="outlined" disabled={exceptionBusy} onClick={assignException}>
                  Assign exception
                </Button>
              ) : null}
              {factorException.status === 'open' || factorException.status === 'assigned' ? (
                <Stack spacing={1} sx={{ mt: 1 }}>
                  <TextField
                    size="small"
                    label="Approved factor id"
                    value={exceptionFactorId}
                    onChange={(event) => setExceptionFactorId(event.target.value)}
                  />
                  <TextField
                    size="small"
                    label="Resolution reason"
                    value={exceptionReason}
                    onChange={(event) => setExceptionReason(event.target.value)}
                    helperText="At least 8 characters. The server uses an active approved factor."
                  />
                  <TextField
                    size="small"
                    label="Evidence reference"
                    value={exceptionEvidence}
                    onChange={(event) => setExceptionEvidence(event.target.value)}
                    helperText={exceptionEvidence.trim() ? '' : 'An evidence reference is required.'}
                  />
                  {exceptionNotice ? <Alert severity="success" sx={{ mb: 1 }}>{exceptionNotice}</Alert> : null}
                  {exceptionError ? <Typography variant="body2" color="error">{exceptionError}</Typography> : null}
                  <Button
                    variant="contained"
                    disabled={
                      exceptionBusy
                      || exceptionReason.trim().length < 8
                      || (
                        factorException.exceptionType !== 'outdated_factor'
                        && factorException.exceptionType !== 'source_verification_required'
                        && !exceptionFactorId.trim()
                      )
                    }
                    onClick={resolveException}
                  >
                    Resolve exception
                  </Button>
                </Stack>
              ) : null}
            </Fold>
          ) : null}
          <Fold embedded={embedded} title="Decision history">
            {historyError ? (
              <Alert severity="error" action={<Button color="inherit" size="small" onClick={() => setHistoryAttempt((value) => value + 1)}>Retry</Button>}>
                {historyError}
              </Alert>
            ) : decisionHistory.length === 0 ? (
              <Typography variant="body2" color="text.secondary">
                No expert decision history is recorded for this transaction.
              </Typography>
            ) : decisionHistory.map((entry) => (
              <Box key={entry.decisionId} sx={{ mt: 1 }}>
                <Stack direction="row" spacing={1} alignItems="center">
                  <Typography variant="body2" sx={{ fontWeight: 700 }}>{decisionLabel(entry.decision)}</Typography>
                  {entry.isCurrent ? <Chip size="small" label="Current decision" /> : null}
                </Stack>
                <Typography variant="body2" color="text.secondary">
                  {`${entry.reviewerName || 'Expert'}${entry.reviewedAt ? ` · ${new Date(entry.reviewedAt).toLocaleString()}` : ''}`}
                </Typography>
                {entry.note ? <Typography variant="body2">{entry.note}</Typography> : null}
              </Box>
            ))}
          </Fold>
          <Box sx={{ display: 'grid', gridTemplateColumns: embedded ? '1fr 1fr' : { xs: '1fr', sm: '1fr 1fr 1fr' }, gap: 1.5, mt: 2 }}>
            <Fact label="Date" value={facts.when || 'No date'} />
            <Fact label="Amount" value={facts.amount} />
            <Fact label="Vendor" value={facts.vendor} />
          </Box>
          <Typography variant="body1" sx={{ mt: 2, fontWeight: 700 }}>
            {`Current result ${facts.kilograms} kg CO2e`}
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>{facts.factorLine}</Typography>
          {facts.formula ? (
            <Typography variant="body2" color="text.secondary">{facts.formula}</Typography>
          ) : null}
          {row.resolution && row.businessStatus !== 'Rejected' ? (
            <Box sx={{ mt: 2 }}>
              <Typography variant="subtitle2">{resolutionHeadline(row)}</Typography>
              <Typography variant="body2">{row.resolution.expertAction}</Typography>
              <Typography variant="body2" color="text.secondary">{row.resolution.companyAction}</Typography>
            </Box>
          ) : null}
          {facts.subcategory ? (
            <Typography variant="body2" sx={{ mt: 1 }}>{`Subcategory ${facts.subcategory}`}</Typography>
          ) : null}
          <Stack direction="row" spacing={1} sx={{ mt: 2 }} flexWrap="wrap" useFlexGap>
            <Button variant="contained" onClick={() => setStep('recommendation')}>See the recommendation</Button>
            {embedded ? null : (
              <Button variant="text" onClick={() => setStep('send')}>Send back to the company</Button>
            )}
            {embedded || !onReject ? null : (
              <Button variant="text" color="error" disabled={busy} onClick={(event) => { rejectOpenerRef.current = event.currentTarget; setRejectReason(''); setRejectOpen(true); }}>
                Reject this transaction
              </Button>
            )}
          </Stack>
        </Paper>
      ) : null}

      {step === 'recommendation' ? (
        <Paper variant="outlined" sx={{ p: 2 }}>
          <Typography variant="h6" sx={{ fontWeight: 800 }}>Recommendation</Typography>
          {row.recommendation && row.recommendation.available !== false ? (
            <>
              <Typography variant="subtitle1" sx={{ mt: 1, fontWeight: 700 }}>{row.recommendation.title}</Typography>
              <Typography variant="body2" sx={{ mt: 1 }}>{row.recommendation.action}</Typography>
              {facts.suggestion ? (
                <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>{facts.suggestion}</Typography>
              ) : null}
            </>
          ) : row.recommendation ? (
            <>
              <Typography variant="subtitle1" sx={{ mt: 1, fontWeight: 700 }}>{row.recommendation.title}</Typography>
              <Typography variant="body2" sx={{ mt: 1 }}>{row.recommendation.action}</Typography>
            </>
          ) : (
            <Typography variant="body2" sx={{ mt: 1 }}>This row has no stored recommendation yet.</Typography>
          )}
          {assistance ? (
            <Box sx={{ mt: 2 }}>
              <Typography variant="subtitle2">
                {assistance.referToRecommendation
                  ? 'Refer to this recommendation'
                  : (assistance.outcome === 'manual_classification' || assistance.outcome === 'no_registry_mapping'
                    ? 'No activity factor in the registry'
                    : 'More information is required')}
              </Typography>
              <Typography variant="body2">{assistance.message}</Typography>
              {assistance.apply?.factorLabel ? (
                <Typography variant="body2" sx={{ mt: 0.5 }}>{`Suggested factor ${assistance.apply.factorLabel}`}</Typography>
              ) : null}
            </Box>
          ) : null}
          <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mt: 2 }}>
            <Button variant="outlined" disabled={busy || askingId === row._id} onClick={() => onAskAgent(row)}>
              {askingId === row._id ? 'Asking the agent' : 'Ask the correction agent'}
            </Button>
            <Button
              variant="contained"
              disabled={!recommendationCanApply(row, assistance)}
              onClick={() => applyRecommendation(row, assistance?.apply || null)}
            >
              Use this recommendation
            </Button>
            <Button variant="text" onClick={() => setStep('understand')}>Back</Button>
          </Stack>
        </Paper>
      ) : null}

      {step === 'correct' ? (
        <Paper variant="outlined" sx={{ p: 2 }}>
          <Typography variant="h6" sx={{ fontWeight: 800 }}>Correct the calculation</Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5, mb: 2 }}>
            Enter the category, quantity, and unit. The rupee amount is not the activity.
          </Typography>
          {waiting ? (
            <Typography variant="body2">This row is waiting for the company. Correct it after the reply arrives.</Typography>
          ) : (
            <Box sx={{ display: 'grid', gap: 1 }}>
              <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', md: '1.4fr 0.8fr 0.8fr' }, gap: 1 }}>
              <TextField
                select
                size="small"
                label="Category"
                value={categoryValue}
                onChange={(event) => setDrafts((current) => ({ ...current, [row._id]: { ...draft, category: event.target.value } }))}
              >
                {REVIEW_CATEGORIES.map((item) => <MenuItem key={item} value={item}>{categoryLabel(item)}</MenuItem>)}
              </TextField>
              <TextField
                size="small"
                label="Quantity"
                value={draft.quantity}
                onChange={(event) => setDrafts((current) => ({ ...current, [row._id]: { ...draft, quantity: event.target.value } }))}
              />
              <TextField
                select
                size="small"
                label="Unit"
                value={draft.unit}
                onChange={(event) => setDrafts((current) => ({ ...current, [row._id]: { ...draft, unit: event.target.value } }))}
              >
                <MenuItem value="">Choose a unit</MenuItem>
                {units.map((unit) => <MenuItem key={unit} value={unit}>{unit}</MenuItem>)}
              </TextField>
              </Box>
              <ExpertScope3LinkFields
                value={draft.scope3Category || ''}
                onChange={(next) => setDrafts((current) => ({ ...current, [row._id]: { ...draft, scope3Category: next } }))}
              />
            </Box>
          )}
          {embedded ? null : (
          <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mt: 2 }}>
            <Button
              variant="contained"
              disabled={
                busy
                || waiting
                || row.settled
                || draft.quantity === ''
                || !draft.unit
                || categoryNeedsRegisteredActivity(categoryValue)
                || resolutionBlocksApproval(row)
              }
              onClick={() => onCorrect(row, { ...draft, category: categoryValue, subcategory: draft.subcategory })}
            >
              Correct and approve
            </Button>
            {canApproveAsIs(row) ? (
              <Button variant="outlined" disabled={busy || resolutionBlocksApproval(row)} onClick={() => onConfirm(row, scope3CategoryPayload(draft.scope3Category))}>Approve</Button>
            ) : null}
            <Button variant="text" onClick={() => setStep('send')}>Send back to the company</Button>
          </Stack>
          )}
        </Paper>
      ) : null}

      {step === 'send' ? (
        <Paper variant="outlined" sx={{ p: 2 }}>
          <Typography variant="h6" sx={{ fontWeight: 800 }}>Send back to the company</Typography>
          {request ? (
            <Box sx={{ mt: 1 }}>
              <Typography variant="subtitle2">
                {request.kind === 'bill' ? 'Asked the company to upload the bill' : 'Asked the company for more information'}
              </Typography>
              <Typography variant="body2">{request.question}</Typography>
              {request.status === 'answered' ? (
                <Typography variant="body2" sx={{ mt: 0.5 }}>
                  {`Company reply: ${request.reply || 'No written reply.'}${request.documentName ? ` Bill: ${request.documentName}.` : ''}`}
                </Typography>
              ) : (
                <Typography variant="body2" sx={{ mt: 0.5 }}>
                  Carbon stays unchanged until the company replies. Then review the reply and correct the calculation.
                </Typography>
              )}
              {waiting ? (
                <Button sx={{ mt: 1 }} variant="text" disabled={busy} onClick={() => onCancelRequest(row)}>Cancel this request</Button>
              ) : null}
              {row.informationRequest?.status === 'answered' && onReviewReply ? (
                <Button sx={{ mt: 1 }} variant="outlined" disabled={busy} onClick={() => onReviewReply(row)}>Mark reply reviewed</Button>
              ) : null}
            </Box>
          ) : (
            <>
              <TextField
                fullWidth
                size="small"
                label="What is missing"
                sx={{ mt: 2 }}
                value={questions[row._id] || ''}
                placeholder="The bill does not show the diesel litres"
                onChange={(event) => setQuestions((current) => ({ ...current, [row._id]: event.target.value }))}
              />
              <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mt: 2 }}>
                <Button
                  variant="outlined"
                  disabled={busy || (questions[row._id] || '').trim().length < 8}
                  onClick={() => onAskCompany(row, { kind: 'details', question: (questions[row._id] || '').trim() })}
                >
                  Ask for more information
                </Button>
                <Button
                  variant="outlined"
                  disabled={busy || (questions[row._id] || '').trim().length < 8}
                  onClick={() => onAskCompany(row, { kind: 'bill', question: (questions[row._id] || '').trim() })}
                >
                  Ask for the bill
                </Button>
              </Stack>
            </>
          )}
          <Fold embedded={embedded} title="Clarification history">
            {clarificationRounds.length === 0 ? (
              <Typography variant="body2">No clarification history is recorded for this transaction.</Typography>
            ) : clarificationRounds.map((round, index) => (
              <Box key={round.roundId || String(index)} sx={{ mt: 1.5 }}>
                <Typography variant="subtitle2">{`Round ${index + 1} · ${round.roundId}`}</Typography>
                {round.events.map((event, eventIndex) => (
                  <Box key={`${round.roundId}-${event.eventType}-${event.occurredAt || eventIndex}`} sx={{ mt: 0.5 }}>
                    <Typography variant="body2">{clarificationEventLabel(event.eventType)}</Typography>
                    {event.previousRequest?.question ? (
                      <Typography variant="body2">{`Earlier request: ${event.previousRequest.question}`}</Typography>
                    ) : null}
                    {event.question ? <Typography variant="body2">{`Question: ${event.question}`}</Typography> : null}
                    {event.reply ? <Typography variant="body2">{`Reply: ${event.reply}`}</Typography> : null}
                    {event.documentName || event.documentId ? (
                      <Typography variant="body2">
                        {`Document: ${event.documentName || 'Attached file'}${event.documentId ? ` (${event.documentId})` : ''}`}
                      </Typography>
                    ) : null}
                    <Typography variant="caption" color="text.secondary" component="p">
                      {[event.actorName, event.actorRole, formatClarificationTime(event.occurredAt)].filter(Boolean).join(' · ')}
                    </Typography>
                  </Box>
                ))}
              </Box>
            ))}
          </Fold>
          <Button sx={{ mt: 2 }} variant="text" onClick={() => setStep('understand')}>Back to the transaction</Button>
        </Paper>
      ) : null}

      {row.settled ? (
        <Typography variant="body2">{`Approved. ${Number(row.settledKilograms ?? row.co2Emissions) || 0} kg CO2e.`}</Typography>
      ) : null}
    </Stack>
    </Box>
      {embedded && !waiting ? (
        <Box sx={{ flex: '0 0 auto', bgcolor: 'background.paper', borderTop: 1, borderColor: 'divider', px: 0.5, pt: 1.5, pb: 0.5 }}>
          <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
            <Button
              variant="contained"
              disabled={
                busy
                || waiting
                || Boolean(row.settled)
                || draft.quantity === ''
                || !draft.unit
                || categoryNeedsRegisteredActivity(categoryValue)
                || resolutionBlocksApproval(row)
              }
              onClick={() => onCorrect(row, { ...draft, category: categoryValue, subcategory: draft.subcategory })}
            >
              Correct and approve
            </Button>
            {canApproveAsIs(row) ? (
              <Button variant="outlined" disabled={busy || resolutionBlocksApproval(row)} onClick={() => onConfirm(row, scope3CategoryPayload(draft.scope3Category))}>Approve</Button>
            ) : null}
            {onReject ? (
              <Button variant="text" color="error" disabled={busy} onClick={(event) => { rejectOpenerRef.current = event.currentTarget; setRejectReason(''); setRejectOpen(true); }}>
                Reject
              </Button>
            ) : null}
            <Button variant="text" onClick={() => setStep('send')}>Ask company</Button>
          </Stack>
        </Box>
      ) : null}
    </Box>
      <Dialog open={rejectOpen} onClose={closeRejectDialog} fullWidth maxWidth="sm">
        <DialogTitle>Reject this transaction?</DialogTitle>
        <DialogContent>
          <Typography variant="body2" sx={{ mb: 1 }}>
            The voucher and its current calculation stay on the record. This does not delete the evidence.
          </Typography>
          <TextField
            autoFocus
            fullWidth
            required
            size="small"
            label="Rejection reason"
            value={rejectReason}
            onChange={(event) => setRejectReason(event.target.value)}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={closeRejectDialog}>Cancel</Button>
          <Button
            color="error"
            variant="contained"
            disabled={busy || rejectReason.trim().length === 0 || !row}
            onClick={() => {
              if (!row || !onReject) return;
              onReject(row, rejectReason.trim());
              closeRejectDialog();
            }}
          >
            Reject transaction
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

const Fold: React.FC<{ embedded?: boolean; title: string; children: React.ReactNode }> = ({ embedded, title, children }) => (
  embedded ? (
    <Accordion disableGutters sx={{ mt: 2, '&:before': { display: 'none' } }}>
      <AccordionSummary expandIcon={<ExpandMoreIcon />}>
        <Typography variant="subtitle2">{title}</Typography>
      </AccordionSummary>
      <AccordionDetails>{children}</AccordionDetails>
    </Accordion>
  ) : (
    <Box sx={{ mt: 2 }}>
      <Typography variant="subtitle2">{title}</Typography>
      {children}
    </Box>
  )
);

const Fact: React.FC<{ label: string; value: string }> = ({ label, value }) => (
  <Box sx={{
    p: 1.25,
    borderRadius: 1,
    border: 1,
    borderColor: 'divider',
    bgcolor: 'action.hover',
    minWidth: 0,
  }}
  >
    <Typography variant="caption" color="text.secondary">{label}</Typography>
    <Typography variant="body2" sx={{ fontWeight: 700, overflow: 'hidden', textOverflow: 'ellipsis' }}>{value}</Typography>
  </Box>
);

export default ExpertReviewWizard;
