import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Skeleton,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';

export interface FactorExceptionQueueRow {
  exceptionId: string;
  exceptionType: string;
  severity?: string;
  status?: string;
  reason?: string;
  message?: string;
  factorId?: string;
  attemptedFactorId?: string;
  evidenceDocumentId?: string;
  batchId?: string;
  detectedAt?: string;
  transactionId: string;
  msmeId: string;
  description?: string;
  companyName?: string;
  blocksReport?: boolean;
}

const ExpertFactorExceptionQueue: React.FC<{
  onOpen: (row: FactorExceptionQueueRow) => void;
}> = ({ onOpen }) => {
  const [rows, setRows] = useState<FactorExceptionQueueRow[]>([]);
  const [cursor, setCursor] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [partial, setPartial] = useState(false);

  const load = useCallback(async (append: boolean, nextCursor?: string | null) => {
    setLoading(true);
    setError(null);
    try {
      const response = await axios.get(buildApiUrl('/expert/factor-exceptions'), {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
        params: { limit: 25, cursor: nextCursor || undefined },
      });
      const page: FactorExceptionQueueRow[] = response.data?.data?.exceptions || [];
      setRows((current) => {
        if (!append) return page;
        const seen = new Set(current.map((row) => row.exceptionId));
        return [...current, ...page.filter((row) => !seen.has(row.exceptionId))];
      });
      const more = response.data?.data?.nextCursor || null;
      setCursor(more);
      setPartial(response.data?.data?.totalsScope === 'loaded_page' || Boolean(more));
    } catch (loadError: any) {
      setError(loadError?.response?.data?.message || 'Factor exceptions could not be loaded.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load(false);
  }, [load]);

  return (
    <Stack spacing={2}>
      {partial ? (
        <Typography variant="caption" color="text.secondary">More exceptions remain on the server.</Typography>
      ) : null}
      {error ? (
        <Alert severity="error" action={<Button color="inherit" size="small" onClick={() => void load(false)}>Retry</Button>}>
          {error}
        </Alert>
      ) : null}
      {loading && rows.length === 0 ? (
        <Stack spacing={1} aria-label="Loading factor exceptions">
          {[0, 1, 2].map((key) => <Skeleton key={key} variant="rounded" height={88} />)}
        </Stack>
      ) : null}
      {!loading && rows.length === 0 ? <Typography variant="body2">No open factor exceptions.</Typography> : null}
      {rows.length > 0 ? (
        <Box sx={{ overflowX: 'auto' }}>
          <Table size="small" aria-label="Factor exceptions" sx={{ minWidth: 760 }}>
            <TableHead>
              <TableRow>
                <TableCell>Company</TableCell>
                <TableCell>Transaction</TableCell>
                <TableCell>Type</TableCell>
                <TableCell>Status</TableCell>
                <TableCell>Severity</TableCell>
                <TableCell>Blocks report</TableCell>
                  <TableCell>Detected</TableCell>
                  <TableCell>Reason</TableCell>
                  <TableCell>Message</TableCell>
                  <TableCell>Factor</TableCell>
                  <TableCell>Evidence</TableCell>
                  <TableCell>Batch</TableCell>
                  <TableCell>Review</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {rows.map((row) => (
                <TableRow key={row.exceptionId}>
                  <TableCell>{row.companyName || 'Company name unavailable'}</TableCell>
                  <TableCell>{row.description || row.transactionId}</TableCell>
                  <TableCell>{row.exceptionType}</TableCell>
                  <TableCell>{row.status || 'Status unavailable'}</TableCell>
                  <TableCell>{row.severity || 'unspecified'}</TableCell>
                  <TableCell>{row.blocksReport ? 'Yes' : 'No'}</TableCell>
                  <TableCell>{row.detectedAt ? new Date(row.detectedAt).toLocaleString() : 'Detected date unavailable'}</TableCell>
                  <TableCell>{row.reason || 'Reason unavailable'}</TableCell>
                  <TableCell>{row.message || 'Message unavailable'}</TableCell>
                  <TableCell>{[row.factorId, row.attemptedFactorId].filter(Boolean).join(' · ') || 'Factor unavailable'}</TableCell>
                  <TableCell>{row.evidenceDocumentId || 'No evidence id'}</TableCell>
                  <TableCell>{row.batchId || 'Batch unavailable'}</TableCell>
                  <TableCell>
                    <Button
                      size="small"
                      variant="contained"
                      aria-label={`Review ${row.description || 'transaction'} for ${row.companyName || 'company'}`}
                      onClick={() => onOpen(row)}
                      disabled={!row.transactionId || !row.msmeId}
                    >
                      Review transaction
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </Box>
      ) : null}
      {cursor ? (
        <Button onClick={() => void load(true, cursor)} disabled={loading}>Load more exceptions</Button>
      ) : null}
    </Stack>
  );
};

export default ExpertFactorExceptionQueue;
