import React from 'react';
import {
  Box,
  Button,
  Checkbox,
  Chip,
  Skeleton,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  Tooltip,
  Typography,
} from '@mui/material';
import { categoryLabel } from './expertReviewCategories';
import {
  ExpertReviewRow,
  canSelectForSharedAssessment,
  isRowApproved,
  resolutionHeadline,
  reviewClassLabel,
  rowHoldBadges,
  similarOpenRows,
  voucherFacts,
} from './expertReviewDisplay';

const ellipsis = {
  overflow: 'hidden',
  textOverflow: 'ellipsis',
  whiteSpace: 'nowrap',
} as const;

export const ExpertStatusMark: React.FC<{ approved: boolean; badges: string[] }> = ({ approved, badges }) => (
  <Stack direction="row" spacing={0.5} alignItems="center" useFlexGap flexWrap="wrap" sx={{ position: 'relative' }}>
    <Tooltip title={approved ? 'Approved' : 'Open'}>
      <Box
        aria-label={approved ? 'Approved' : 'Open'}
        sx={{
          width: 10,
          height: 10,
          borderRadius: '50%',
          bgcolor: approved ? 'success.main' : 'error.main',
          flex: '0 0 auto',
        }}
      />
    </Tooltip>
    <Box component="span" sx={{ position: 'absolute', width: 1, height: 1, overflow: 'hidden', clip: 'rect(0 0 0 0)' }}>
      {approved ? 'Approved' : 'Open'}
    </Box>
    {badges.map((badge) => (
      <Chip key={badge} size="small" color="warning" variant="outlined" label={badge} />
    ))}
  </Stack>
);

const ExpertReviewTable: React.FC<{
  rows: ExpertReviewRow[];
  allRows: ExpertReviewRow[];
  selectedIds: string[];
  activeId?: string | null;
  loading?: boolean;
  onToggle: (id: string) => void;
  onSelectSimilar: (row: ExpertReviewRow) => void;
  onOpen: (id: string) => void;
  emptyMessage?: string;
}> = ({ rows, allRows, selectedIds, activeId, loading = false, onToggle, onSelectSimilar, onOpen, emptyMessage }) => (
  <Table size="small" aria-label="Calculation review table" sx={{ tableLayout: 'fixed', width: '100%', minWidth: { xs: 680, lg: 0 } }}>
    <TableHead>
      <TableRow>
        <TableCell padding="checkbox" sx={{ width: '4%' }} />
        <TableCell sx={{ width: '12%' }}>Status</TableCell>
        <TableCell sx={{ width: '24%' }}>Transaction</TableCell>
        <TableCell sx={{ width: '14%' }}>Category</TableCell>
        <TableCell sx={{ width: '10%' }}>Qty</TableCell>
        <TableCell sx={{ width: '20%' }}>Reason</TableCell>
        <TableCell align="right" sx={{ width: '16%' }}>kg CO2e</TableCell>
      </TableRow>
    </TableHead>
    <TableBody>
      {loading ? (
        Array.from({ length: 6 }, (_, index) => (
          <TableRow key={`skeleton-${index}`}>
            {Array.from({ length: 7 }, (__, cell) => (
              <TableCell key={cell}><Skeleton height={22} /></TableCell>
            ))}
          </TableRow>
        ))
      ) : rows.length === 0 ? (
        <TableRow>
          <TableCell colSpan={7}>
            <Typography variant="body2">{emptyMessage || 'No transactions on this page match the filter.'}</Typography>
          </TableCell>
        </TableRow>
      ) : rows.map((row) => {
        const approved = isRowApproved(row);
        const facts = voucherFacts(row);
        const selectable = canSelectForSharedAssessment(row);
        const similarCount = similarOpenRows(allRows, row).length;
        const reason = resolutionHeadline(row) || row.businessStatusReason || reviewClassLabel(row);
        const quantity = row.quantity != null ? String(row.quantity) : '—';
        return (
          <TableRow
            key={row._id}
            hover
            selected={activeId === row._id}
            onClick={() => onOpen(row._id)}
            sx={{ cursor: 'pointer' }}
          >
            <TableCell padding="checkbox" onClick={(event) => event.stopPropagation()}>
              <Tooltip title={selectable ? 'Include this row in the page selection.' : 'Approved rows and open clarifications stay out of the selection.'}>
                <span>
                  <Checkbox
                    checked={selectedIds.includes(row._id)}
                    disabled={!selectable}
                    inputProps={{ 'aria-label': `Select ${row.description || 'this transaction'}` }}
                    onChange={() => onToggle(row._id)}
                  />
                </span>
              </Tooltip>
            </TableCell>
            <TableCell>
              <ExpertStatusMark approved={approved} badges={rowHoldBadges(row)} />
            </TableCell>
            <TableCell>
              <Typography variant="body2" sx={{ fontWeight: 700, ...ellipsis }} title={row.description || 'Untitled voucher'}>
                {row.description || 'Untitled voucher'}
              </Typography>
              <Typography variant="caption" color="text.secondary" display="block" sx={ellipsis}>
                {[facts.when, facts.vendor].filter(Boolean).join(' · ') || 'No date or vendor'}
              </Typography>
            </TableCell>
            <TableCell>
              <Typography variant="body2" sx={ellipsis}>{categoryLabel(row.category)}</Typography>
            </TableCell>
            <TableCell>
              <Typography variant="body2" sx={ellipsis}>{`${quantity}${row.unit ? ` ${row.unit}` : ''}`}</Typography>
            </TableCell>
            <TableCell>
              <Typography variant="body2" sx={ellipsis} title={reason}>{reason}</Typography>
            </TableCell>
            <TableCell align="right" onClick={(event) => event.stopPropagation()}>
              <Stack direction="row" spacing={0.5} justifyContent="flex-end" alignItems="center" flexWrap="wrap" useFlexGap>
                <Typography variant="body2" sx={{ mr: 0.5 }}>{facts.kilograms}</Typography>
                {similarCount > 1 ? (
                  <Button
                    size="small"
                    aria-label={`Select similar to ${row.description || 'this transaction'}`}
                    onClick={() => onSelectSimilar(row)}
                  >
                    {`Similar (${similarCount})`}
                  </Button>
                ) : null}
                <Button
                  size="small"
                  variant="outlined"
                  aria-label={`Open ${row.description || 'this transaction'}`}
                  onClick={() => onOpen(row._id)}
                >
                  Open
                </Button>
              </Stack>
            </TableCell>
          </TableRow>
        );
      })}
    </TableBody>
  </Table>
);

export default ExpertReviewTable;
