import React, { useCallback, useEffect, useState } from 'react';
import { Alert, Box, Button, Chip, Stack, Typography } from '@mui/material';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';

interface Scope3Option {
  value: number;
  label: string;
  short: string;
  included: boolean;
}

interface Scope3Boundary {
  scope3OutOfBoundarySummary?: string;
  keptCompanyNote?: boolean;
  options: Scope3Option[];
}

const ExpertScope3Boundary: React.FC<{ msmeId: string }> = ({ msmeId }) => {
  const [options, setOptions] = useState<Scope3Option[]>([]);
  const [selected, setSelected] = useState<number[]>([]);
  const [note, setNote] = useState('');
  const [keptCompanyNote, setKeptCompanyNote] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const applyBoundary = (boundary: Scope3Boundary) => {
    const list = Array.isArray(boundary?.options) ? boundary.options : [];
    setOptions(list);
    setSelected(list.filter((option) => option.included).map((option) => option.value));
    setNote(boundary?.scope3OutOfBoundarySummary || '');
    setKeptCompanyNote(Boolean(boundary?.keptCompanyNote));
  };

  const load = useCallback(async () => {
    if (!msmeId) return;
    setLoading(true);
    setError(null);
    try {
      const response = await axios.get(buildApiUrl(`/expert/users/${msmeId}/scope3-boundary`), {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
      });
      applyBoundary(response.data?.data || { options: [] });
    } catch (loadError: any) {
      setOptions([]);
      setError(loadError?.response?.data?.message || 'The value-chain categories could not be loaded.');
    } finally {
      setLoading(false);
    }
  }, [msmeId]);

  useEffect(() => {
    void load();
  }, [load]);

  const toggle = (value: number) => {
    setSelected((current) => (
      current.includes(value)
        ? current.filter((item) => item !== value)
        : [...current, value].sort((left, right) => left - right)
    ));
    setNotice(null);
  };

  const save = async () => {
    setSaving(true);
    setError(null);
    setNotice(null);
    try {
      const response = await axios.patch(
        buildApiUrl(`/expert/users/${msmeId}/scope3-boundary`),
        { include: selected },
        { headers: { Authorization: `Bearer ${localStorage.getItem('token')}` } },
      );
      applyBoundary(response.data?.data || { options: [] });
      setNotice(response.data?.message || 'Value-chain categories saved.');
    } catch (saveError: any) {
      setError(saveError?.response?.data?.message || 'The value-chain categories could not be saved.');
    } finally {
      setSaving(false);
    }
  };

  if (!msmeId || (!loading && options.length === 0 && !error)) return null;

  return (
    <Box data-testid="expert-scope3-boundary" sx={{ mb: 2 }}>
      <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
        Categories that start outside the usual value chain
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
        Turn on category 8, 10, 11, 12, 13, 14, or 15 when this company has that activity. A voucher in a category that stays out is left out of the inventory. Turning a category on does not create kilograms.
      </Typography>
      {error ? <Alert severity="error" sx={{ mb: 1 }}>{error}</Alert> : null}
      {notice ? <Alert severity="success" sx={{ mb: 1 }}>{notice}</Alert> : null}
      {loading ? <Typography variant="body2">Loading value-chain categories…</Typography> : null}
      {options.length > 0 ? (
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
          {options.map((option) => {
            const on = selected.includes(option.value);
            return (
              <Chip
                key={option.value}
                component="button"
                type="button"
                label={`${option.value} ${option.short}`}
                color={on ? 'primary' : 'default'}
                variant={on ? 'filled' : 'outlined'}
                aria-pressed={on}
                onClick={() => toggle(option.value)}
                data-testid={`expert-scope3-cat-${option.value}`}
              />
            );
          })}
        </Stack>
      ) : null}
      {note ? (
        <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
          {keptCompanyNote
            ? `The company note stays: ${note}`
            : `Outside the value chain: ${note}`}
        </Typography>
      ) : null}
      <Button
        size="small"
        variant="outlined"
        sx={{ mt: 1 }}
        disabled={loading || saving || options.length === 0}
        onClick={() => { void save(); }}
      >
        Save value-chain categories
      </Button>
    </Box>
  );
};

export default ExpertScope3Boundary;
