import React, { useCallback, useEffect, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';
import ExpertPortalLayout from './ExpertPortalLayout';
import {
  ExpertNavAction,
  ExpertSection,
  applyExpertNav,
  contextFromSearch,
  contextToSearch,
} from './expertNavigation';
import ExpertCalculationReview from './ExpertCalculationReview';
import ExpertUserList, { ConsultantUserRow } from './ExpertUserList';
import ExpertCompanyWorkspace from './ExpertCompanyWorkspace';
import ExpertSubmissionQueue from './ExpertSubmissionQueue';
import ExpertOverview from './ExpertOverview';
import ExpertEmissionReview from './ExpertEmissionReview';
import ExpertFactorExceptionQueue from './ExpertFactorExceptionQueue';
import ExpertHoldList from './ExpertHoldList';
import ExpertOpenCalculations from './ExpertOpenCalculations';

const ExpertDashboard: React.FC = () => {
  const [params, setParams] = useSearchParams();
  const context = contextFromSearch(params);
  const section: ExpertSection = context.section;
  const userId = context.user;
  const [users, setUsers] = useState<ConsultantUserRow[]>([]);
  const [summary, setSummary] = useState<Record<string, any> | null>(null);
  const [companyTotalsScope, setCompanyTotalsScope] = useState<'loaded_page' | 'complete'>('loaded_page');
  const [summaryError, setSummaryError] = useState<string | null>(null);
  const [usersError, setUsersError] = useState<string | null>(null);
  const [overviewLoading, setOverviewLoading] = useState(true);
  const [picked, setPicked] = useState<ConsultantUserRow | null>(null);

  const loadOverview = useCallback(async () => {
    const headers = { Authorization: `Bearer ${localStorage.getItem('token')}` };
    const failureMessage = (reason: unknown) => {
      const response = (reason as { response?: { data?: { message?: string } } })?.response;
      return response?.data?.message || 'The overview could not be loaded.';
    };
    setOverviewLoading(true);
    const [userResult, summaryResult] = await Promise.allSettled([
      axios.get(buildApiUrl('/expert/users'), { headers }),
      axios.get(buildApiUrl('/expert/overview-summary'), { headers }),
    ]);
    if (userResult.status === 'fulfilled') {
      setUsers(userResult.value.data?.data?.users || []);
      setCompanyTotalsScope(userResult.value.data?.data?.totalsScope === 'complete' ? 'complete' : 'loaded_page');
      setUsersError(null);
    } else {
      setUsers([]);
      setCompanyTotalsScope('loaded_page');
      setUsersError(failureMessage(userResult.reason));
    }
    if (summaryResult.status === 'fulfilled') {
      setSummary(summaryResult.value.data?.data || null);
      setSummaryError(null);
    } else {
      setSummary(null);
      setSummaryError(failureMessage(summaryResult.reason));
    }
    setOverviewLoading(false);
  }, []);

  useEffect(() => {
    void loadOverview();
  }, [loadOverview]);

  useEffect(() => {
    const canonical = contextToSearch(contextFromSearch(params));
    const raw: Record<string, string> = { section: params.get('section') || 'overview' };
    ['user', 'msme', 'batch', 'tx', 'view'].forEach((key) => {
      const value = params.get(key);
      if (value) raw[key] = value;
    });
    const same = Object.keys(canonical).length === Object.keys(raw).length
      && Object.entries(canonical).every(([key, value]) => raw[key] === value);
    if (!same) setParams(canonical, { replace: true });
  }, [params, setParams]);

  const navigate = (action: ExpertNavAction) => {
    setParams(contextToSearch(applyExpertNav(context, action)));
  };

  const go = (next: ExpertSection) => navigate({ type: 'sidebar', section: next });

  const selected = users.find((user) => user.userId === userId) || (picked && picked.userId === userId ? picked : null);
  const companyNames = Object.fromEntries(users.filter((user) => user.msmeId).map((user) => [user.msmeId, user.companyName || user.name]));

  const title = {
    overview: 'Your review workspace',
    queue: 'Submissions',
    companies: 'Companies',
    review: selected ? (selected.companyName || selected.name) : 'Calculations',
    exceptions: 'Factor Exceptions',
    classification: 'Activity Classification',
  }[section];

  const subtitle = {
    overview: 'A clear view of pending work across the companies and submissions you review.',
    queue: context.batch
      ? 'This is the selected submission. Approve only the rows the server still accepts.'
      : 'Each row is one company submission. Open it to review that batch, then approve only the rows the server still accepts.',
    companies: 'Find companies, understand their review workload, and continue work in their dedicated workspace.',
    review: 'Company-wide calculation review for legacy rows. Stamped submission batches are approved in the submission workspace.',
    exceptions: 'Open factor exceptions that can block an official report. Resolving an exception does not approve the row.',
    classification: 'Rows held for an activity factor, marked for admin emission review, or calculated as spend amount times an emission factor.',
  }[section];

  const breadcrumbs = section === 'review'
    ? [
      { label: 'Companies', onClick: () => go('companies') },
      { label: selected?.companyName || selected?.name || 'Review' },
    ]
    : [{ label: 'Expert' }, { label: section === 'overview' ? 'Overview' : title }];

  return (
    <ExpertPortalLayout title={title} subtitle={subtitle} section={section} onSection={(next) => go(next)} breadcrumbs={breadcrumbs}>
      {section === 'overview' ? (
        <ExpertOverview
          users={users}
          summary={summary}
          companyTotalsScope={companyTotalsScope}
          summaryError={summaryError}
          usersError={usersError}
          loading={overviewLoading}
          onRetry={() => { void loadOverview(); }}
          onSection={(next) => go(next)}
          onOpenDestination={(destination) => navigate({ type: 'metric', section: destination.section, view: destination.view })}
          onOpenSubmission={(row) => navigate({ type: 'overview-submission', msme: row.msmeId, batch: row.batchId })}
          onReview={(user) => { setPicked(user); navigate({ type: 'company-calculations', msme: user.msmeId, user: user.userId }); }}
        />
      ) : null}
      {section === 'exceptions' ? (
        <ExpertFactorExceptionQueue
          onOpen={(row) => navigate({ type: 'factor-to-calculation', msme: row.msmeId, tx: row.transactionId, batch: row.batchId })}
        />
      ) : null}
      {section === 'queue' ? (
        <ExpertSubmissionQueue
          companyNames={companyNames}
          msmeId={context.msme}
          batchId={context.batch}
          listView={context.view}
          onBack={() => navigate({ type: 'submissions-list' })}
          onOpenBatch={(row) => navigate({ type: 'overview-submission', msme: row.msmeId, batch: row.batchId })}
          onCheckCalculations={(row) => navigate({ type: 'submission-calculations', msme: row.msmeId, batch: row.batchId })}
        />
      ) : null}
      {section === 'companies' ? (
        context.msme ? (
          <ExpertCompanyWorkspace
            msmeId={context.msme}
            userId={context.user}
            batchId={context.batch}
            onOpenCalculations={() => navigate({ type: 'company-calculations', msme: context.msme, user: context.user, batch: context.batch })}
            onOpenTransaction={(tx, batch) => navigate({ type: 'factor-to-calculation', msme: context.msme, tx, batch: batch || context.batch })}
            onOpenSubmission={(row) => navigate({ type: 'overview-submission', msme: row.msmeId, batch: row.batchId })}
            onBack={() => navigate({ type: 'companies-directory' })}
          />
        ) : (
          <ExpertUserList
            onSelect={(user) => { setPicked(user); navigate({ type: 'company-calculations', msme: user.msmeId, user: user.userId }); }}
            onOpen={(user) => { setPicked(user); navigate({ type: 'overview-company', msme: user.msmeId, user: user.userId }); }}
          />
        )
      ) : null}
      {section === 'review' && (context.view === 'clarifications' || context.view === 'bills') ? (
        <ExpertHoldList kind={context.view === 'bills' ? 'bills' : 'clarifications'} />
      ) : null}
      {section === 'review' && context.view === 'open-calculations' ? (
        <ExpertOpenCalculations
          onOpen={(row) => navigate({ type: 'factor-to-calculation', msme: row.msmeId, tx: row.id, batch: row.batchId || '' })}
        />
      ) : null}
      {section === 'review' && !context.view ? (
        <ExpertCalculationReview
          selectedUser={selected || undefined}
          companyId={context.msme}
          batchId={context.batch}
          focusTransactionId={context.tx}
          chooseCompany={!userId && !context.msme}
          onBack={() => navigate(context.batch
            ? { type: 'overview-submission', msme: context.msme, batch: context.batch }
            : { type: 'calculations-company', msme: context.msme })}
        />
      ) : null}
      {section === 'classification' ? <ExpertEmissionReview /> : null}
    </ExpertPortalLayout>
  );
};

export default ExpertDashboard;
