export type ExpertSection = 'overview' | 'queue' | 'companies' | 'review' | 'exceptions' | 'classification';

export const EXPERT_SECTIONS: ExpertSection[] = [
  'overview',
  'queue',
  'companies',
  'review',
  'exceptions',
  'classification',
];

export type ExpertView = '' | 'open-submissions' | 'clarifications' | 'bills' | 'open-calculations';

export interface ExpertContext {
  section: ExpertSection;
  user: string;
  msme: string;
  batch: string;
  tx: string;
  view: ExpertView;
}

export type ExpertNavAction =
  | { type: 'sidebar'; section: ExpertSection }
  | { type: 'overview-company'; msme: string; user?: string }
  | { type: 'overview-submission'; msme: string; batch: string }
  | { type: 'company-submissions'; msme: string }
  | { type: 'company-calculations'; msme: string; user?: string; batch?: string }
  | { type: 'submission-calculations'; msme: string; batch: string }
  | { type: 'calculations-company'; msme: string }
  | { type: 'factor-to-calculation'; msme: string; tx: string; batch?: string }
  | { type: 'metric'; section: ExpertSection; view?: ExpertView }
  | { type: 'companies-directory' }
  | { type: 'submissions-list' };

const clean = (value: unknown) => String(value || '').trim();

const allowedView = (section: ExpertSection, view: string): ExpertView => {
  if (section === 'queue' && view === 'open-submissions') return 'open-submissions';
  if (section === 'review' && (view === 'clarifications' || view === 'bills' || view === 'open-calculations')) return view;
  return '';
};

export const sanitizeExpertContext = (
  input: Partial<Omit<ExpertContext, 'section' | 'view'>> & { section?: string; view?: string }
): ExpertContext => {
  const requested = clean(input.section);
  const section = EXPERT_SECTIONS.includes(requested as ExpertSection)
    ? requested as ExpertSection
    : 'overview';
  const msme = clean(input.msme);
  const batch = msme ? clean(input.batch) : '';
  const user = msme ? clean(input.user) : '';
  const tx = msme ? clean(input.tx) : '';
  const view = allowedView(section, clean(input.view));
  return { section, user, msme, batch, tx, view };
};

export const contextFromSearch = (params: { get: (key: string) => string | null }): ExpertContext => (
  sanitizeExpertContext({
    section: params.get('section') || 'overview',
    user: params.get('user') || '',
    msme: params.get('msme') || '',
    batch: params.get('batch') || '',
    tx: params.get('tx') || '',
    view: params.get('view') || '',
  })
);

export const contextToSearch = (context: ExpertContext): Record<string, string> => {
  const cleanContext = sanitizeExpertContext(context);
  const params: Record<string, string> = { section: cleanContext.section };
  if (cleanContext.msme) params.msme = cleanContext.msme;
  if (cleanContext.user) params.user = cleanContext.user;
  if (cleanContext.batch) params.batch = cleanContext.batch;
  if (cleanContext.tx) params.tx = cleanContext.tx;
  if (cleanContext.view) params.view = cleanContext.view;
  return params;
};

const sameCompanyUser = (current: ExpertContext, msme: string) => (
  current.msme === msme ? current.user : ''
);

const sidebarContext = (current: ExpertContext, section: ExpertSection): ExpertContext => {
  if (section === 'overview' || section === 'classification') {
    return { section, user: '', msme: '', batch: '', tx: '', view: '' };
  }
  if (section === 'exceptions') {
    return { section, user: '', msme: current.msme, batch: '', tx: '', view: '' };
  }
  if (section === 'companies') {
    return {
      section,
      user: current.user,
      msme: current.msme,
      batch: current.msme ? current.batch : '',
      tx: current.msme ? current.tx : '',
      view: '',
    };
  }
  if (section === 'queue') {
    return {
      section,
      user: '',
      msme: current.msme,
      batch: current.msme ? current.batch : '',
      tx: '',
      view: '',
    };
  }
  return {
    section: 'review',
    user: current.msme ? current.user : '',
    msme: current.msme,
    batch: current.msme ? current.batch : '',
    tx: current.msme ? current.tx : '',
    view: '',
  };
};

export const applyExpertNav = (current: ExpertContext, action: ExpertNavAction): ExpertContext => {
  switch (action.type) {
    case 'sidebar':
      return sidebarContext(current, action.section);
    case 'overview-company':
      return sanitizeExpertContext({
        section: 'companies',
        msme: action.msme,
        user: action.user || '',
        batch: '',
        tx: '',
      });
    case 'overview-submission':
      return sanitizeExpertContext({
        section: 'queue',
        msme: action.msme,
        batch: action.batch,
        user: '',
        tx: '',
      });
    case 'company-submissions':
      return sanitizeExpertContext({
        section: 'queue',
        msme: action.msme,
        batch: '',
        user: '',
        tx: '',
      });
    case 'company-calculations':
      return sanitizeExpertContext({
        section: 'review',
        msme: action.msme,
        user: action.user || '',
        batch: action.batch || '',
        tx: '',
      });
    case 'submission-calculations':
      return sanitizeExpertContext({
        section: 'review',
        msme: action.msme,
        batch: action.batch,
        user: sameCompanyUser(current, action.msme),
        tx: '',
      });
    case 'calculations-company':
      return sanitizeExpertContext({
        section: 'companies',
        msme: action.msme,
        user: sameCompanyUser(current, action.msme),
        batch: '',
        tx: '',
      });
    case 'factor-to-calculation':
      return sanitizeExpertContext({
        section: 'review',
        msme: action.msme,
        tx: action.tx,
        batch: action.batch || '',
        user: '',
      });
    case 'metric':
      return sanitizeExpertContext({
        section: action.section,
        view: action.view || '',
        msme: '',
        user: '',
        batch: '',
        tx: '',
      });
    case 'companies-directory':
      return { section: 'companies', user: '', msme: '', batch: '', tx: '', view: '' };
    case 'submissions-list':
      return sanitizeExpertContext({
        section: 'queue',
        msme: current.msme,
        user: '',
        batch: '',
        tx: '',
      });
    default:
      return sanitizeExpertContext(current);
  }
};
