import React, { useCallback, useEffect, useRef, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  MenuItem,
  Paper,
  Skeleton,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';
import { THEME_MODE_STORAGE_KEY } from '../../context/ThemeModeContext';
import { ExpertStatusMark } from './ExpertReviewTable';

interface SubmissionCounts {
  total: number;
  approved: number;
  pending: number;
  rejected?: number;
  waitingForBill: number;
  additionalInformation: number;
  reviewable: number;
  failed?: number;
  bulkApproval?: {
    eligible: number;
    alreadyApproved: number;
    awaitingCalculation: number;
    clarificationOpen: number;
    billRequired: number;
    missingQuantity: number;
    excluded: number;
    notStamped: number;
    storedCurrentApproval: number;
    clarificationAnswered: number;
    calculationFailed?: number;
    staleStoredReview: number;
    rejected?: number;
  };
  excluded?: number;
  clarificationAnswered?: number;
  clarificationAnsweredCount?: number;
  excludedCount?: number;
}

interface SubmissionRow {
  batchId: string;
  msmeId: string;
  companyName?: string;
  status: string;
  source: string;
  fileName?: string;
  provider?: string;
  submittedAt?: string;
  counts: SubmissionCounts;
  firstOpenedAt?: string | null;
  historicalFirstOpenedAt?: string | null;
  explicitFirstOpenedAt?: string | null;
  explicitReviewStarted?: boolean;
}

export const displayVendor = (vendor: unknown): string => {
  if (typeof vendor === 'string') return vendor.trim();
  if (!vendor || typeof vendor !== 'object') return '';
  const record = vendor as { name?: unknown; category?: unknown; location?: unknown };
  const name = typeof record.name === 'string' ? record.name.trim() : '';
  const category = typeof record.category === 'string' ? record.category.trim() : '';
  const location = typeof record.location === 'string' ? record.location.trim() : '';
  return [name, category, location].filter(Boolean).join(' · ');
};

interface BatchTransaction {
  _id: string;
  date?: string;
  vendor?: unknown;
  description?: string;
  amount?: number;
  category?: string;
  quantity?: number;
  unit?: string;
  emissionFactor?: number | null;
  co2Emissions?: number | null;
  formula?: string;
  calculationStatus?: string;
  billStatus?: string;
  reviewStatus?: string;
  bulkDisposition?: string;
  informationRequest?: { status?: string } | null;
  businessStatus?: string;
  businessStatusReason?: string;
}

const token = () => localStorage.getItem('token');
const authHeaders = () => ({ Authorization: `Bearer ${token()}` });

const sourceLabel = (source: string) => (source === 'connector' ? 'Data Connector' : 'Excel');

const BULK_DISPOSITION_LABELS: Record<string, string> = {
  eligible: 'Eligible',
  already_approved: 'Already approved',
  awaiting_calculation: 'Waiting for calculation',
  clarification_open: 'Clarification open',
  clarification_answered: 'Reply waiting for review',
  bill_required: 'Bill required',
  missing_quantity: 'Quantity required',
  calculation_failed: 'Calculation failed',
  excluded: 'Excluded',
  not_stamped: 'Outside expert approval',
  rejected: 'Rejected',
};

const queueHoldBadges = (item: BatchTransaction) => {
  const badges: string[] = [];
  if (item.businessStatus === 'Rejected' || item.bulkDisposition === 'rejected') badges.push('Rejected');
  if (item.bulkDisposition === 'excluded') badges.push('Excluded');
  if (item.bulkDisposition === 'bill_required' || item.billStatus) badges.push('Bill required');
  if (item.informationRequest?.status === 'open' || item.bulkDisposition === 'clarification_open') badges.push('Clarification');
  else if (item.informationRequest?.status === 'answered') badges.push('Reply waiting');
  return badges;
};

const reviewCell = (item: BatchTransaction) => {
  const disposition = item.bulkDisposition ? BULK_DISPOSITION_LABELS[item.bulkDisposition] : '';
  const notes: string[] = [];
  if (item.bulkDisposition && item.bulkDisposition !== 'already_approved' && item.reviewStatus === 'approved') {
    notes.push('current approval stored');
  }
  if (item.billStatus) notes.push(item.billStatus);
  if (item.informationRequest?.status === 'answered') notes.push('clarification answered');
  else if (item.informationRequest?.status) notes.push(item.informationRequest.status);
  return [item.businessStatus, disposition || item.reviewStatus || '', ...notes].filter(Boolean).join(' · ');
};

const statusColor = (status: string): 'success' | 'warning' | 'error' | 'default' => {
  const value = status.toLowerCase();
  if (value.includes('fail') || value.includes('reject')) return 'error';
  if (value.includes('partial') || value.includes('information') || value.includes('bill')) return 'warning';
  if (value.includes('approv')) return 'success';
  return 'default';
};

const statusDot = (status: string) => {
  const color = statusColor(status);
  if (color === 'default') return 'text.disabled';
  return `${color}.main`;
};

const MOTION = '@media (prefers-reduced-motion: reduce)';
const focusRing = {
  '&:focus-visible': { outline: '2px solid #2e7d32', outlineOffset: 2 },
};

const finiteNumber = (value: unknown): number | null => (
  typeof value === 'number' && Number.isFinite(value) ? value : null
);

const countText = (value: unknown) => {
  const count = finiteNumber(value);
  return count == null ? 'Unavailable' : String(count);
};

const batchCountLine = (counts: SubmissionCounts) => {
  const bulk = counts?.bulkApproval;
  if (!bulk) return 'Eligibility counts are not loaded yet.';
  return `Total ${countText(counts.total)}. Pending ${countText(counts.pending)}. Eligible ${countText(bulk.eligible)}. Rejected ${countText(counts.rejected ?? bulk.rejected)}. Approved ${countText(counts.approved)}. Failed ${countText(bulk.calculationFailed ?? counts.failed)}. Answered clarifications ${countText(bulk.clarificationAnswered)}.`;
};

const useNarrowTransactions = () => {
  const [narrow, setNarrow] = useState(false);
  useEffect(() => {
    if (typeof window.matchMedia !== 'function') return undefined;
    const query = window.matchMedia('(max-width: 899px)');
    if (!query || typeof query.matches !== 'boolean') return undefined;
    const apply = () => setNarrow(query.matches);
    apply();
    query.addEventListener?.('change', apply);
    return () => query.removeEventListener?.('change', apply);
  }, []);
  return narrow;
};

const focusWithRing = (node: HTMLElement | null | undefined) => {
  if (!node) return;
  node.focus();
  const dark = window.localStorage.getItem(THEME_MODE_STORAGE_KEY) === 'dark';
  node.style.outline = `2px solid ${dark ? '#ffffff' : '#2e7d32'}`;
  node.style.outlineOffset = '2px';
  const clear = () => {
    node.style.outline = '';
    node.style.outlineOffset = '';
    node.removeEventListener('blur', clear);
  };
  node.addEventListener('blur', clear);
};

const ExpertSubmissionQueue: React.FC<{
  companyNames?: Record<string, string>;
  msmeId?: string;
  batchId?: string;
  listView?: string;
  onBack?: () => void;
  onOpenBatch?: (row: { msmeId: string; batchId: string }) => void;
  onCheckCalculations?: (row: { msmeId: string; batchId: string }) => void;
}> = ({ companyNames = {}, msmeId = '', batchId = '', listView = '', onBack, onOpenBatch, onCheckCalculations }) => {
  const [rows, setRows] = useState<SubmissionRow[]>([]);
  const [cursor, setCursor] = useState<string | null>(null);
  const [source, setSource] = useState('');
  const [nameQuery, setNameQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [submittedFrom, setSubmittedFrom] = useState('');
  const [submittedTo, setSubmittedTo] = useState('');
  const [pagingNote, setPagingNote] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [openBatch, setOpenBatch] = useState<SubmissionRow | null>(null);
  const [transactions, setTransactions] = useState<BatchTransaction[]>([]);
  const [txCursor, setTxCursor] = useState<string | null>(null);
  const [txPageCursor, setTxPageCursor] = useState<string | null>(null);
  const [txHistory, setTxHistory] = useState<Array<string | null>>([]);
  const [txLoading, setTxLoading] = useState(false);
  const [search, setSearch] = useState('');
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [rejectTarget, setRejectTarget] = useState<BatchTransaction | null>(null);
  const approveOpenerRef = useRef<HTMLButtonElement>(null);
  const rejectOpenerRef = useRef<HTMLButtonElement | null>(null);
  const restoreFocus = (node: HTMLElement | null) => {
    window.setTimeout(() => focusWithRing(node), 0);
  };
  const closeReject = () => {
    setRejectTarget(null);
    restoreFocus(rejectOpenerRef.current);
  };
  const closeConfirm = () => {
    setConfirmOpen(false);
    restoreFocus(approveOpenerRef.current);
  };
  const [rejectReason, setRejectReason] = useState('');
  const [notice, setNotice] = useState<string | null>(null);
  const [failedAction, setFailedAction] = useState<'list' | 'batch' | 'approve' | 'reject' | null>(null);
  const narrow = useNarrowTransactions();
  const workspaceMode = Boolean(batchId && msmeId);

  const load = useCallback(async (append: boolean, nextCursor?: string | null) => {
    setLoading(true);
    setError(null);
    try {
      const response = await axios.get(buildApiUrl('/expert/submissions'), {
        headers: authHeaders(),
        params: {
          source: source || undefined,
          msmeId: msmeId || undefined,
          status: statusFilter || undefined,
          approval: listView === 'open-submissions' ? 'open' : undefined,
          q: nameQuery.trim() || undefined,
          submittedFrom: submittedFrom || undefined,
          submittedTo: submittedTo || undefined,
          cursor: nextCursor || undefined,
          limit: 20,
        },
      });
      const payload = response.data?.data?.submissions;
      if (!Array.isArray(payload)) {
        setRows([]);
        setCursor(null);
        setFailedAction('list');
        setError('Submissions could not be loaded.');
        return;
      }
      const page = payload as SubmissionRow[];
      setRows((current) => {
        if (!append) return page;
        const seen = new Set(current.map((item) => `${item.msmeId}-${item.batchId}`));
        return [...current, ...page.filter((item) => !seen.has(`${item.msmeId}-${item.batchId}`))];
      });
      setCursor(response.data?.data?.nextCursor || null);
      setPagingNote(response.data?.data?.paging || '');
      setFailedAction(null);
    } catch (loadError: any) {
      setFailedAction('list');
      setError(loadError?.response?.data?.message || 'Submissions could not be loaded.');
    } finally {
      setLoading(false);
    }
  }, [source, msmeId, statusFilter, submittedFrom, submittedTo, nameQuery, listView]);

  useEffect(() => {
    if (workspaceMode) return;
    setOpenBatch(null);
    setTransactions([]);
    void load(false);
  }, [load, workspaceMode]);

  const openTransactions = async (
    row: SubmissionRow,
    cursor: string | null,
    history: Array<string | null>,
  ) => {
    if (row.status) setOpenBatch(row);
    setTxLoading(true);
    setError(null);
    try {
      const response = await axios.get(
        buildApiUrl(`/expert/submissions/${row.msmeId}/${encodeURIComponent(row.batchId)}/transactions`),
        {
          headers: authHeaders(),
          params: { cursor: cursor || undefined, limit: 50, search: search || undefined },
        },
      );
      const page = response.data?.data?.transactions || [];
      setTransactions(page);
      setTxPageCursor(cursor);
      setTxHistory(history);
      setTxCursor(response.data?.data?.nextCursor || null);
      setFailedAction(null);
      if (response.data?.data?.summary) {
        setOpenBatch({ ...row, ...response.data.data.summary, batchId: row.batchId, msmeId: row.msmeId });
      }
    } catch (loadError: any) {
      setFailedAction('batch');
      setError(loadError?.response?.data?.message || 'Transactions could not be loaded.');
      if (!row.status) {
        setOpenBatch(null);
        setTransactions([]);
      }
    } finally {
      setTxLoading(false);
    }
  };

  const openTransactionsRef = useRef(openTransactions);
  openTransactionsRef.current = openTransactions;

  useEffect(() => {
    if (!workspaceMode) return;
    void openTransactionsRef.current({
      batchId,
      msmeId,
      status: '',
      source: '',
      counts: {
        total: Number.NaN,
        approved: Number.NaN,
        pending: Number.NaN,
        waitingForBill: Number.NaN,
        additionalInformation: Number.NaN,
        reviewable: Number.NaN,
      },
    }, null, []);
  }, [workspaceMode, batchId, msmeId]);

  const startReview = async () => {
    if (!openBatch) return;
    setTxLoading(true);
    setError(null);
    try {
      const response = await axios.post(
        buildApiUrl(`/expert/submissions/${openBatch.msmeId}/${openBatch.batchId}/start-review`),
        {},
        { headers: authHeaders() },
      );
      const summary = response.data?.data?.summary;
      if (summary) setOpenBatch((current) => current ? { ...current, ...summary, companyName: current.companyName || summary.companyName } : summary);
      setNotice(response.data?.message || 'Review started.');
    } catch (saveError: any) {
      setError(saveError?.response?.data?.message || 'Review could not be started.');
    } finally {
      setTxLoading(false);
    }
  };

  const approveBatch = async () => {
    if (!openBatch) return;
    closeConfirm();
    setTxLoading(true);
    try {
      const response = await axios.post(buildApiUrl('/expert/calculation-review/confirm-open'), {
        msmeId: openBatch.msmeId,
        batchId: openBatch.batchId,
      }, { headers: authHeaders() });
      const result = response.data?.data;
      const parts = [
        response.data?.message || 'Submission updated.',
        result ? `Approved ${result.approved ?? 0}. Skipped ${result.skipped ?? 0}. Stale ${result.stale ?? 0}. Failed ${result.failed ?? 0}.` : '',
        result?.partial ? 'This approval was partial.' : '',
      ].filter(Boolean);
      setNotice(parts.join(' '));
      await openTransactions(openBatch, txPageCursor, txHistory);
      await load(false);
    } catch (saveError: any) {
      setFailedAction('approve');
      setError(saveError?.response?.data?.message || 'The submission could not be approved.');
    } finally {
      setTxLoading(false);
    }
  };

  const rejectTransaction = async () => {
    if (!rejectTarget || rejectReason.trim().length === 0) return;
    const target = rejectTarget;
    const reason = rejectReason.trim();
    closeReject();
    setRejectReason('');
    setTxLoading(true);
    try {
      const response = await axios.post(
        buildApiUrl(`/expert/transactions/${target._id}/calculation-review/reject`),
        { reason, msmeId: openBatch?.msmeId || msmeId, batchId: openBatch?.batchId || batchId },
        { headers: authHeaders() },
      );
      const saved = response.data?.data;
      setTransactions((current) => current.map((item) => (
        item._id === target._id
          ? {
            ...item,
            businessStatus: saved?.businessStatus || 'Rejected',
            businessStatusReason: saved?.businessStatusReason || `Expert rejected this transaction: ${reason}`,
            bulkDisposition: 'rejected',
          }
          : item
      )));
      setNotice(response.data?.message || 'Transaction rejected.');
    } catch (saveError: any) {
      setFailedAction('reject');
      setRejectTarget(target);
      setRejectReason(reason);
      setError(saveError?.response?.data?.message || 'The rejection could not be saved.');
    } finally {
      setTxLoading(false);
    }
  };

  const companyLabel = (row: SubmissionRow) => row.companyName || companyNames[row.msmeId] || 'Company name unavailable';
  const retryFailed = () => {
    if (failedAction === 'approve') {
      setError(null);
      setConfirmOpen(true);
      return;
    }
    if (failedAction === 'reject') {
      setError(null);
      return;
    }
    if (failedAction === 'batch' || workspaceMode) {
      const row = openBatch || {
        batchId,
        msmeId,
        status: '',
        source: '',
        counts: {
          total: Number.NaN,
          approved: Number.NaN,
          pending: Number.NaN,
          waitingForBill: Number.NaN,
          additionalInformation: Number.NaN,
          reviewable: Number.NaN,
        },
      };
      void openTransactions(row, null, []);
      return;
    }
    void load(false);
  };
  const leaveWorkspace = () => {
    if (onBack) onBack();
    else setOpenBatch(null);
  };
  const visible = rows.filter((row) => {
    if (statusFilter && row.status !== statusFilter) return false;
    return true;
  });
  const filtersActive = Boolean(source || nameQuery.trim() || statusFilter || submittedFrom || submittedTo);
  const counts = openBatch?.counts;

  return (
    <Stack spacing={2} sx={{ minWidth: 0, [MOTION]: { '& *': { animation: 'none', transition: 'none' } } }}>
      {!workspaceMode ? <Paper variant="outlined" sx={{ p: 2 }}>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
          Company, source, status, and submitted dates are sent to the server. Company or file text searches every stamped submission, not only this page. A date-only end date includes that whole UTC day. {pagingNote}
        </Typography>
        <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', alignItems: 'center' }}>
          <TextField size="small" label="Company or file" value={nameQuery} onChange={(event) => setNameQuery(event.target.value)} sx={{ flex: '1 1 180px', minWidth: 0, maxWidth: '100%' }} />
          <TextField select size="small" label="Status" value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)} sx={{ flex: '1 1 180px', minWidth: 0, maxWidth: '100%' }}>
            <MenuItem value="">All statuses</MenuItem>
            {['Pending Expert Review', 'Under Review', 'Partially Approved', 'Additional Information Required', 'Waiting for Bill', 'Calculation Failed', 'Processing', 'Approved', 'Submitted'].map((item) => (
              <MenuItem key={item} value={item}>{item}</MenuItem>
            ))}
          </TextField>
          <TextField size="small" label="Submitted from" type="date" value={submittedFrom} onChange={(event) => setSubmittedFrom(event.target.value)} InputLabelProps={{ shrink: true }} sx={{ flex: '1 1 150px' }} />
          <TextField size="small" label="Submitted to" type="date" value={submittedTo} onChange={(event) => setSubmittedTo(event.target.value)} InputLabelProps={{ shrink: true }} sx={{ flex: '1 1 150px' }} />
          <TextField select size="small" label="Submission type" value={source} onChange={(event) => setSource(event.target.value)} sx={{ flex: '1 1 160px', minWidth: 0, maxWidth: '100%' }}>
            <MenuItem value="">All types</MenuItem>
            <MenuItem value="excel">Excel</MenuItem>
            <MenuItem value="connector">Data Connector</MenuItem>
          </TextField>
          {filtersActive ? (
            <Button size="small" onClick={() => { setNameQuery(''); setStatusFilter(''); setSource(''); setSubmittedFrom(''); setSubmittedTo(''); }}>Clear filters</Button>
          ) : null}
        </Box>
      </Paper> : null}
      {notice ? <Alert severity="success" onClose={() => setNotice(null)}>{notice}</Alert> : null}
      {error ? <Alert severity="error" action={<Button color="inherit" size="small" onClick={retryFailed} sx={focusRing}>Retry</Button>}>{error}</Alert> : null}
      {!workspaceMode && loading && rows.length === 0 ? (
        <Stack spacing={1} aria-label="Loading submissions">
          {[0, 1, 2].map((key) => <Skeleton key={key} variant="rounded" height={88} />)}
        </Stack>
      ) : null}
      {!workspaceMode && !loading && !error && rows.length === 0 ? <Typography variant="body2">No stamped submissions are waiting.</Typography> : null}
      {!workspaceMode && !loading && !error && rows.length > 0 && visible.length === 0 ? <Typography variant="body2">No submissions match these filters.</Typography> : null}
      {!workspaceMode ? visible.map((row) => (
        <Paper key={`${row.msmeId}-${row.batchId}`} variant="outlined" sx={{ p: 2 }}>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.5} justifyContent="space-between" alignItems={{ sm: 'center' }}>
            <Box sx={{ minWidth: 0, flex: 1 }}>
              <Stack direction="row" spacing={1} alignItems="center">
                <Box aria-hidden sx={{ width: 10, height: 10, borderRadius: '50%', bgcolor: statusDot(row.status), flexShrink: 0 }} />
                <Typography variant="subtitle1" sx={{ fontWeight: 700, minWidth: 0 }}>{companyLabel(row)}</Typography>
              </Stack>
              <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" useFlexGap sx={{ mt: 0.5 }}>
                <Chip size="small" label={row.status} color={statusColor(row.status)} variant="outlined" />
                <Chip size="small" label={sourceLabel(row.source)} variant="outlined" />
              </Stack>
              <Typography variant="body2" color="text.secondary" sx={{ mt: 0.75 }}>
                {row.submittedAt ? new Date(row.submittedAt).toLocaleString() : 'Submission date unavailable'}
              </Typography>
              <Typography variant="caption" color="text.secondary" display="block">
                {row.fileName || row.provider || row.batchId}
              </Typography>
              <Typography variant="caption" display="block" sx={{ mt: 0.5 }}>
                {batchCountLine(row.counts)}
              </Typography>
            </Box>
            <Button variant="contained" aria-label={companyNames[row.msmeId] ? `Open submission for ${companyNames[row.msmeId]}` : 'Open selected submission'} sx={{ ...focusRing, alignSelf: { xs: 'stretch', sm: 'center' }, flexShrink: 0 }} onClick={() => (onOpenBatch ? onOpenBatch({ msmeId: row.msmeId, batchId: row.batchId }) : void openTransactions(row, null, []))}>Open submission</Button>
          </Stack>
        </Paper>
      )) : null}
      {!workspaceMode && cursor ? <Button onClick={() => void load(true, cursor)} disabled={loading} sx={focusRing}>Load more submissions</Button> : null}

      {openBatch || workspaceMode ? (
        <Paper variant="outlined" sx={{ p: 2, minWidth: 0 }}>
          <Button size="small" onClick={leaveWorkspace} sx={{ ...focusRing, mb: 1.5, textTransform: 'none' }}>Back to submissions</Button>
          <Typography variant="h6" component="h2" sx={{ fontWeight: 700, overflowWrap: 'anywhere' }}>{openBatch ? companyLabel(openBatch) : (companyNames[msmeId || ''] || 'Company name unavailable')}</Typography>
          <Typography variant="body2" color="text.secondary" sx={{ overflowWrap: 'anywhere' }}>
            {openBatch?.status ? `${sourceLabel(openBatch.source || 'excel')} · ${openBatch.status}` : 'Status unavailable'}
            {openBatch?.fileName ? ` · ${openBatch.fileName}` : ''}
          </Typography>
          {openBatch?.historicalFirstOpenedAt && !openBatch.explicitReviewStarted ? (
            <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>
              This submission has an earlier transaction open time. Start Review has not been recorded.
            </Typography>
          ) : null}
          <Typography variant="caption" color="text.secondary" display="block" sx={{ overflowWrap: 'anywhere' }}>
            {openBatch?.batchId ? `Batch ${openBatch.batchId}` : `Batch ${batchId || 'unavailable'}`}
          </Typography>
          <Typography variant="body2" sx={{ mt: 0.5 }}>
            {openBatch?.submittedAt ? new Date(openBatch.submittedAt).toLocaleString() : 'Submission date unavailable'}
          </Typography>
          <Typography variant="body2" sx={{ mt: 0.5 }}>
            {openBatch ? batchCountLine(openBatch.counts) : 'Eligibility counts are not loaded yet.'}
          </Typography>
          <Typography variant="caption" color="text.secondary" display="block">
            Rejected rows are counted separately and are not pending work. Each eligibility reason is one row.
          </Typography>
          {openBatch?.status === 'Pending Expert Review' ? (
              <Button size="small" variant="outlined" sx={{ mt: 1, ...focusRing }} onClick={() => void startReview()} disabled={txLoading}>
                Start review
              </Button>
            ) : null}
          {openBatch ? <Paper variant="outlined" sx={{ p: 2, mt: 2, borderColor: 'warning.main' }}>
            <Typography variant="subtitle2">Approve eligible rows</Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
              This approves only rows the server still marks eligible. Calculation completion does not make a row eligible.
            </Typography>
            {counts?.bulkApproval ? (
              <Typography variant="body2" sx={{ mb: 1 }}>
                {`Eligible ${countText(counts.bulkApproval.eligible)}. Already approved ${countText(counts.bulkApproval.alreadyApproved)}. Waiting for calculation ${countText(counts.bulkApproval.awaitingCalculation)}. Open clarification ${countText(counts.bulkApproval.clarificationOpen)}. Reply not reviewed ${countText(counts.bulkApproval.clarificationAnswered)}. Calculation failed ${countText(counts.bulkApproval.calculationFailed)}. Bill required ${countText(counts.bulkApproval.billRequired)}. Quantity required ${countText(counts.bulkApproval.missingQuantity)}. Excluded ${countText(counts.bulkApproval.excluded)}. Rejected ${countText(counts.bulkApproval.rejected)}.`}
              </Typography>
            ) : (
              <Typography variant="body2" sx={{ mb: 1 }}>
                Eligibility counts are not loaded yet.
              </Typography>
            )}
            {finiteNumber(counts?.bulkApproval?.eligible) === 0 ? (
              <Typography variant="body2" sx={{ mb: 1 }}>No eligible rows to approve.</Typography>
            ) : null}
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1}>
              <Button ref={approveOpenerRef} variant="contained" color="warning" onClick={() => setConfirmOpen(true)} disabled={!counts?.bulkApproval || finiteNumber(counts.bulkApproval.eligible) == null || counts.bulkApproval.eligible === 0} sx={focusRing}>
                Approve eligible rows in this submission
              </Button>
              {onCheckCalculations && openBatch ? (
                <Button variant="outlined" onClick={() => onCheckCalculations({ msmeId: openBatch.msmeId, batchId: openBatch.batchId })} sx={focusRing}>
                  Check calculations
                </Button>
              ) : null}
            </Stack>
          </Paper> : txLoading ? (
            <Stack spacing={1} sx={{ mb: 1 }} aria-label="Loading transactions">
              {[0, 1, 2].map((key) => <Skeleton key={key} variant="rounded" height={36} />)}
            </Stack>
          ) : null}
          {openBatch ? <>
          <Box sx={{ display: 'flex', gap: 1, my: 1, flexWrap: 'wrap' }}>
            <TextField
              size="small"
              label="Search transactions"
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' && openBatch) {
                  event.preventDefault();
                  void openTransactions(openBatch, null, []);
                }
              }}
              sx={{ flex: '1 1 180px', minWidth: 0, maxWidth: '100%' }}
            />
            <Button size="small" variant="outlined" disabled={!openBatch} onClick={() => openBatch && void openTransactions(openBatch, null, [])} sx={focusRing}>Search</Button>
          </Box>
          {txLoading && transactions.length === 0 ? (
            <Stack spacing={1} sx={{ mb: 1 }} aria-label="Loading transactions">
              {[0, 1, 2].map((key) => <Skeleton key={key} variant="rounded" height={36} />)}
            </Stack>
          ) : null}
          {narrow ? (
            <Stack spacing={1} sx={{ minWidth: 0 }}>
              {transactions.map((item) => (
                <Box key={item._id} sx={{ border: '1px solid', borderColor: 'divider', borderRadius: 1.5, p: 1.5, minWidth: 0 }}>
                  <Typography variant="subtitle2" sx={{ overflowWrap: 'anywhere' }}>{item.description || 'Description unavailable'}</Typography>
                  <Typography variant="body2">{displayVendor(item.vendor) || 'Vendor unavailable'}</Typography>
                  <Typography variant="caption" display="block">{item.date ? new Date(item.date).toLocaleDateString() : 'Date unavailable'}{item.amount == null ? '' : ` · ${item.amount}`}</Typography>
                  <Typography variant="body2" sx={{ mt: 0.5 }}>{reviewCell(item) || 'Status unavailable'}</Typography>
                  <Typography variant="caption" display="block">
                    {`Calculation ${item.calculationStatus || 'unavailable'}. Factor ${item.emissionFactor == null ? 'unavailable' : item.emissionFactor}. Carbon ${item.co2Emissions == null ? 'unavailable' : item.co2Emissions}.`}
                    {item.formula ? ` Formula ${item.formula}.` : ''}
                  </Typography>
                  {item.businessStatusReason ? <Typography variant="caption" display="block">{item.businessStatusReason}</Typography> : null}
                  <Button size="small" color="error" aria-label={`Reject ${item.description || 'this transaction'}`} sx={focusRing} onClick={(event) => { rejectOpenerRef.current = event.currentTarget; setRejectReason(''); setRejectTarget(item); }}>
                    Reject
                  </Button>
                </Box>
              ))}
            </Stack>
          ) : (
          <Box sx={{ overflowX: 'auto', maxWidth: '100%' }}>
          <Table size="small" aria-label="Submission transactions" sx={{ minWidth: 720 }}>
            <TableHead>
              <TableRow>
                <TableCell>Date</TableCell>
                <TableCell>Vendor</TableCell>
                <TableCell>Description</TableCell>
                <TableCell>Amount</TableCell>
                <TableCell>Category</TableCell>
                <TableCell>Qty</TableCell>
                <TableCell>Unit</TableCell>
                <TableCell>Factor</TableCell>
                <TableCell>CO2e</TableCell>
                <TableCell>Formula</TableCell>
                <TableCell>Review</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {transactions.map((item) => (
                <TableRow key={item._id}>
                  <TableCell>{item.date ? new Date(item.date).toLocaleDateString() : ''}</TableCell>
                  <TableCell>{displayVendor(item.vendor) || '—'}</TableCell>
                  <TableCell>{item.description}</TableCell>
                  <TableCell>{item.amount}</TableCell>
                  <TableCell>{item.category}</TableCell>
                  <TableCell>{item.quantity}</TableCell>
                  <TableCell>{item.unit}</TableCell>
                  <TableCell>{item.emissionFactor == null ? 'Unavailable' : item.emissionFactor}</TableCell>
                  <TableCell>{item.co2Emissions == null ? 'Unavailable' : item.co2Emissions}</TableCell>
                  <TableCell>{item.formula || ''}</TableCell>
                  <TableCell>
                    <Stack direction="row" spacing={1} alignItems="flex-start">
                      <ExpertStatusMark
                        approved={item.businessStatus === 'Approved' || item.bulkDisposition === 'already_approved'}
                        badges={queueHoldBadges(item)}
                      />
                      <Box sx={{ minWidth: 0 }}>
                        <Typography variant="body2">{reviewCell(item) || 'Status unavailable'}</Typography>
                        <Typography variant="caption" display="block">
                          {`Calculation ${item.calculationStatus || 'unavailable'}`}
                        </Typography>
                        {item.businessStatusReason ? (
                          <Typography variant="caption" display="block">{item.businessStatusReason}</Typography>
                        ) : null}
                        <Button size="small" color="error" aria-label={`Reject ${item.description || 'this transaction'}`} sx={focusRing} onClick={(event) => { rejectOpenerRef.current = event.currentTarget; setRejectReason(''); setRejectTarget(item); }}>
                          Reject
                        </Button>
                      </Box>
                    </Stack>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
          </Box>
          )}
          <Typography variant="caption" display="block" sx={{ mt: 1 }}>
            {`This page lists ${transactions.length} transactions. ${txCursor ? 'More transactions are in this submission.' : 'No further page was returned.'}`}
          </Typography>
          <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mt: 1 }}>
            <Button
              size="small"
              disabled={txHistory.length === 0 || txLoading}
              onClick={() => {
                if (!openBatch) return;
                const previous = txHistory[txHistory.length - 1];
                void openTransactions(openBatch, previous, txHistory.slice(0, -1));
              }}
            >
              Previous page
            </Button>
            {txCursor ? (
              <Button
                size="small"
                disabled={txLoading}
                onClick={() => openBatch && void openTransactions(openBatch, txCursor, [...txHistory, txPageCursor])}
              >
                Next page
              </Button>
            ) : null}
          </Stack>
          </> : null}
        </Paper>
      ) : null}

      <Dialog open={Boolean(rejectTarget)} onClose={closeReject} fullWidth maxWidth="sm">
        <DialogTitle>Reject this transaction?</DialogTitle>
        <DialogContent>
          <Typography variant="body2" sx={{ mb: 1 }}>
            {rejectTarget?.description || 'This voucher'} stays in the ledger with its current calculation.
          </Typography>
          <TextField
            autoFocus
            fullWidth
            required
            size="small"
            label="Rejection reason"
            value={rejectReason}
            onChange={(event) => setRejectReason(event.target.value)}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={closeReject}>Cancel</Button>
          <Button color="error" variant="contained" disabled={rejectReason.trim().length === 0} onClick={() => void rejectTransaction()}>
            Reject transaction
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog open={confirmOpen} onClose={closeConfirm} fullWidth maxWidth="sm">
        <DialogTitle>Approve all eligible transactions in this submission?</DialogTitle>
        <DialogContent>
          {counts?.bulkApproval ? (
            <Typography variant="body2" component="div">
              {`This submission has ${countText(counts.total)} transactions.`}
              <br />
              {`Will be sent for approval: ${counts.bulkApproval.eligible}.`}
              <br />
              {`Already approved and not sent again: ${counts.bulkApproval.alreadyApproved}.`}
              <br />
              {`Waiting for calculation and not sent: ${counts.bulkApproval.awaitingCalculation}.`}
              <br />
              {`Open clarification and not sent: ${counts.bulkApproval.clarificationOpen}. Bill required: ${counts.bulkApproval.billRequired}. Quantity required: ${counts.bulkApproval.missingQuantity}. Excluded: ${counts.bulkApproval.excluded}.`}
              <br />
              {`${counts.bulkApproval.clarificationAnswered} have an answered clarification. A reply is not an approval, and those rows are already included in the groups above.`}
              <br />
              {`${counts.bulkApproval.storedCurrentApproval} have a stored approval that matches the current calculation. A row that is also waiting for calculation stays in that group and is not sent again.`}
              <br />
              {`${counts.bulkApproval.staleStoredReview} have a stored approval that does not match the current calculation. They are sent only when they are in the eligible group.`}
              <br />
              The server reads each row again before writing. A row whose calculation fingerprint changed after this count is skipped.
            </Typography>
          ) : (
            <Typography variant="body2">
              The eligibility breakdown was not returned. Load the submission again before approving.
            </Typography>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={closeConfirm}>Cancel</Button>
          <Button variant="contained" onClick={() => void approveBatch()} disabled={finiteNumber(counts?.bulkApproval?.eligible) == null || counts?.bulkApproval?.eligible === 0}>
            Approve eligible
          </Button>
        </DialogActions>
      </Dialog>
    </Stack>
  );
};

export default ExpertSubmissionQueue;
